// Cyrus: pre-build estimate (client-safe, pure, unit-tested).
//
// Complexity comes from a feature count over the request text (the same idea
// as the build service's router, kept deliberately small here: it only drives
// the hint and the estimate, never what the service actually does).
// Time and cost ranges are anchored on the Phase 0 measurement (2026-10-06,
// 10 real builds on the balanced model: 40-299 s, $0.08-$0.47 API-equivalent,
// avg 160 s / $0.28). The "complex" upper end is extrapolated. Every figure is
// shown to the customer as an estimate.
import { cyrusModel, type CyrusModelId } from "./models";

export type Complexity = "simple" | "standard" | "complex";

const FEATURES: [string, number, RegExp][] = [
  ["menus", 2, /\b(gui|menus?|chest (menu|gui)|inventory (menu|gui)|clicks?)\b/i],
  ["saved data", 1, /\b(saved?|persist\w*|stored?|survive|restarts?|to (a )?file|database)\b/i],
  ["scoreboard", 2, /\b(scoreboard|sidebar|tab ?list|leaderboard|top \d+|boss ?bar)\b/i],
  ["economy", 2, /\b(coins?|money|balance|economy|shop|buy|sell|prices?|pay)\b/i],
  ["regions", 2, /\b(regions?|zones?|claims?|arena|pos1|pos2|corners?)\b/i],
  ["protection", 1, /\b(protect\w*|grief\w*|trusted?|explosions?)\b/i],
  ["mini-game", 3, /\b(mini-?game|rounds?|winner|teams?|lobby|countdown)\b/i],
  ["boss", 2, /\b(boss(?! ?bar)|phases?|minions?|waves?)\b/i],
  ["timers", 1, /\b(every \d*\s*(seconds?|minutes?|hours?)|timer|cooldown|daily|streaks?)\b/i],
  ["quests", 3, /\b(quests?|missions?|achievements?|objectives?)\b/i],
  ["effects", 1, /\b(potion|effects?|particles?|trails?|sounds?|titles?|fireworks?)\b/i],
  ["items", 1, /\b(items?|recipes?|enchant\w*|lore|loot|drops?|rewards?)\b/i],
  ["mobs", 1, /\b(spawns?|mobs?|zombies?|skeletons?|creepers?|entit(y|ies)|npcs?)\b/i],
  ["config", 0.5, /\b(config(urable)?|settings?)\b/i],
  ["permissions", 0.5, /\b(permissions?|operators?|ranks?)\b/i],
];

export type Estimate = {
  complexity: Complexity;
  score: number;
  features: string[];
  commands: number;
  recommended: CyrusModelId;
  minutes: [number, number];
  usd: [number, number];
};

const BASE: Record<Complexity, { min: [number, number]; usd: [number, number] }> = {
  simple: { min: [1, 2], usd: [0.08, 0.18] },
  standard: { min: [2, 4], usd: [0.15, 0.35] },
  complex: { min: [3, 6], usd: [0.3, 0.6] },
};

export function estimate(text: string, model: CyrusModelId, opts: { change?: boolean } = {}): Estimate {
  const t = text || "";
  const features: string[] = [];
  let score = 0;
  for (const [name, w, re] of FEATURES) if (re.test(t)) { features.push(name); score += w; }
  const commands = new Set((t.match(/\/[a-z][a-z0-9_-]{1,24}/gi) || []).map((c) => c.toLowerCase())).size;
  score += Math.max(0, commands - 1) * 0.5;
  score += Math.min(2, Math.floor(t.length / 450));
  const complexity: Complexity = score >= 7.5 ? "complex" : score >= 3 ? "standard" : "simple";
  const recommended: CyrusModelId = complexity === "simple" ? "katara" : complexity === "standard" ? "saka" : "yakko";
  const m = cyrusModel(model);
  const b = BASE[complexity];
  // A change request reads the old code first but usually writes less.
  const k = opts.change ? 0.8 : 1;
  const usd: [number, number] = [round2(b.usd[0] * m.costFactor * k), round2(b.usd[1] * m.costFactor * k)];
  const minutes: [number, number] = [Math.max(1, Math.round(b.min[0] * m.timeFactor * k)), Math.max(1, Math.round(b.min[1] * m.timeFactor * k))];
  if (minutes[1] <= minutes[0]) minutes[1] = minutes[0] + 1;
  return { complexity, score: Math.round(score * 10) / 10, features, commands, recommended, minutes, usd };
}

function round2(n: number) { return Math.max(0.01, Math.round(n * 100) / 100); }

export function fmtUsd([a, b]: [number, number]): string {
  return `$${a.toFixed(2)}–${b.toFixed(2)}`;
}

/** Is the chosen model clearly under-powered (or wasteful) for the request? */
export function modelAdvice(e: Estimate, chosen: CyrusModelId): "ok" | "under" | "over" {
  const rank = { katara: 0, saka: 1, yakko: 2 } as const;
  const d = rank[chosen] - rank[e.recommended];
  return d < 0 ? "under" : d > 0 && e.complexity === "simple" ? "over" : "ok";
}
// Cyrus: customer-facing model, game and version catalogue (client-safe).
//
// The three model names are Cyrus's own. Customers never see the underlying
// model family; the build service maps the Cyrus id (sent as `tier`) to a model.
// and is only read server-side (app/api/mod-builder/builds/route.ts).
import { MB_VERSIONS, MB_DEFAULT_VERSION } from "../modbuilder/types";

export const CYRUS_MODEL_IDS = ["katara", "saka", "yakko"] as const;
export type CyrusModelId = (typeof CYRUS_MODEL_IDS)[number];
export const CYRUS_DEFAULT_MODEL: CyrusModelId = "saka";

export type CyrusModel = {
  id: CyrusModelId;
  name: string;
  /** One line, customer voice. */
  blurb: string;
  /** What it is best at, shown in the picker. */
  bestFor: string;
  /** 1..3 token-spend meter. */
  spend: 1 | 2 | 3;
  spendLabel: string;
  /** Relative AI cost vs Saka (estimate only; see lib/cyrus/estimate.ts). */
  costFactor: number;
  /** Relative wall time vs Saka. */
  timeFactor: number;
  hue: string;
};

export const CYRUS_MODELS: CyrusModel[] = [
  { id: "katara", name: "Katara", blurb: "Fast, for simple mods", bestFor: "Simple mods: a command, a message, a drop table", spend: 1, spendLabel: "Usually spends fewer tokens", costFactor: 0.5, timeFactor: 0.75, hue: "#14c5e4" },
  { id: "saka", name: "Saka", blurb: "Balanced builder", bestFor: "Most mods: menus, saved data, mini-games", spend: 2, spendLabel: "Spends more tokens", costFactor: 1, timeFactor: 1, hue: "#8c3ae9" },
  { id: "yakko", name: "Yakko", blurb: "Deep thinker", bestFor: "Ultra mods: bosses, quests, big systems", spend: 3, spendLabel: "Spends a lot of tokens", costFactor: 1.7, timeFactor: 1.35, hue: "#d623e1" },
];

export const cyrusModel = (id: string | null | undefined): CyrusModel =>
  CYRUS_MODELS.find((m) => m.id === id) ?? CYRUS_MODELS.find((m) => m.id === CYRUS_DEFAULT_MODEL)!;

export function isCyrusModel(v: unknown): v is CyrusModelId {
  return typeof v === "string" && (CYRUS_MODEL_IDS as readonly string[]).includes(v);
}

/**
 * The build service (image modbuilder:0.3+) takes the Cyrus id itself as `tier`:
 * katara -> Haiku 4.5, saka -> Sonnet 5, yakko -> Opus 5 (services/modbuilder).
 * Customers only ever see the Cyrus names.
 */
export const CYRUS_SERVICE_TIER = (id: CyrusModelId) => id;

export type CyrusGame = { id: string; name: string; available: boolean; note: string; versions: readonly string[]; defaultVersion?: string };

/** Only Minecraft (Paper plugins) builds today; the rest are shown as "coming soon". No game logos or art. */
export const CYRUS_GAMES: CyrusGame[] = [
  { id: "minecraft", name: "Minecraft", available: true, note: "Paper / Purpur server plugins", versions: MB_VERSIONS, defaultVersion: MB_DEFAULT_VERSION },
  { id: "valheim", name: "Valheim", available: false, note: "Coming soon", versions: [] },
  { id: "rust", name: "Rust", available: false, note: "Coming soon", versions: [] },
  { id: "terraria", name: "Terraria", available: false, note: "Coming soon", versions: [] },
  { id: "palworld", name: "Palworld", available: false, note: "Coming soon", versions: [] },
  { id: "ark", name: "ARK", available: false, note: "Coming soon", versions: [] },
];

export const CYRUS_STAGES: { key: string; label: string; sub: string }[] = [
  { key: "planning", label: "Planning", sub: "Mapping what to build" },
  { key: "coding", label: "Writing", sub: "Weaving the code" },
  { key: "compiling", label: "Compiling", sub: "Into a real plugin" },
  { key: "repairing", label: "Fixing", sub: "Only if needed" },
  { key: "scanning", label: "Safety", sub: "No internet, no system" },
  { key: "succeeded", label: "Ready", sub: "Download or install" },
];

export const CYRUS_STATUS_LABEL: Record<string, string> = {
  queued: "In line",
  planning: "Planning",
  coding: "Writing code",
  compiling: "Compiling",
  repairing: "Fixing",
  scanning: "Safety check",
  succeeded: "Ready",
  failed: "Didn't build",
};
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { modBuilderUser } from "@/lib/modbuilder/access";

export const NOT_FOUND = () => NextResponse.json({ error: "Not found" }, { status: 404, headers: { "x-robots-tag": "noindex" } });

/** The preview user + their build, or null (callers answer 404 — the feature doesn't exist for anyone else). */
export async function ownedBuild(id: string) {
  const user = await modBuilderUser();
  if (!user) return null;
  const build = await db.modBuild.findUnique({ where: { id } });
  if (!build || build.userId !== user.id) return null;
  return { user, build };
}
import { NextResponse } from "next/server";
import { randomBytes } from "node:crypto";
import { db } from "@/lib/db";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { svcCreate, ModBuilderUnavailable } from "@/lib/modbuilder/client";
import { toView } from "@/lib/modbuilder/store";
import { MB_VERSIONS } from "@/lib/modbuilder/types";
import { checkRateLimit } from "@/lib/rate-limit";
import { NOT_FOUND } from "../_lib";
import { isCyrusModel } from "@/lib/cyrus/models";
import { readCyrusMeta, type CyrusMeta } from "@/lib/cyrus/meta";
import { claimUploads, isUploadId, readAttachment } from "@/lib/cyrus/uploads";
import type { CyrusAttachment } from "@/lib/cyrus/meta";

export const dynamic = "force-dynamic";

const MAX_INFLIGHT = 2;

export async function GET() {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const rows = await db.modBuild.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 50 });
  return NextResponse.json({ builds: rows.map(toView) });
}

export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const prompt = String(body.prompt ?? "").trim();
  const mcVersion = String(body.mcVersion ?? MB_VERSIONS[0]);
  const changeRequest = body.changeRequest ? String(body.changeRequest).trim() : "";
  const baseBuildId = body.baseBuildId ? String(body.baseBuildId) : null;
  // Cyrus (optional, additive): the model picked in the composer and pasted images.
  if (body.model !== undefined && !isCyrusModel(body.model)) return NextResponse.json({ error: "Pick Katara, Saka or Yakko." }, { status: 400 });
  const attachmentIds = Array.isArray(body.attachmentIds) ? body.attachmentIds.filter(isUploadId).slice(0, 4) : [];

  if (!(MB_VERSIONS as readonly string[]).includes(mcVersion)) return NextResponse.json({ error: "Pick a Minecraft version from the list." }, { status: 400 });

  let base = null;
  if (baseBuildId) {
    base = await db.modBuild.findUnique({ where: { id: baseBuildId } });
    if (!base || base.userId !== user.id) return NOT_FOUND();
    if (base.status !== "succeeded") return NextResponse.json({ error: "You can only change a build that finished." }, { status: 400 });
    if (changeRequest.length < 4 || changeRequest.length > 2000) return NextResponse.json({ error: "Describe the change in a few words (up to 2,000 characters)." }, { status: 400 });
  } else if (prompt.length < 12 || prompt.length > 4000) {
    return NextResponse.json({ error: prompt.length < 12 ? "Tell us a bit more about what the plugin should do." : "That's a lot! Keep it under 4,000 characters." }, { status: 400 });
  }

  for (const [k, max, windowMs] of [["mb:create:min", 3, 60_000], ["mb:create:hour", 20, 3_600_000]] as const) {
    const rl = checkRateLimit(`${k}:${user.id}`, { max, windowMs });
    if (!rl.ok) return NextResponse.json({ error: `You're building fast! Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  }
  const inflight = await db.modBuild.count({ where: { userId: user.id, status: { notIn: ["succeeded", "failed"] } } });
  if (inflight >= MAX_INFLIGHT) return NextResponse.json({ error: "You already have builds running. Wait for one to finish first." }, { status: 429 });

  const id = "mb" + randomBytes(10).toString("hex");
  // A change keeps the model its version was built with unless a new one is picked.
  const model = isCyrusModel(body.model) ? body.model : base ? readCyrusMeta(base.cyrus).model : undefined;
  const cyrus: CyrusMeta | null = model || attachmentIds.length ? { ...(model ? { model } : {}) } : null;
  const row = await db.modBuild.create({
    data: {
      id,
      userId: user.id,
      prompt: base ? base.prompt : prompt,
      changeRequest: base ? changeRequest : null,
      baseBuildId: base ? base.id : null,
      rootBuildId: base ? (base.rootBuildId ?? base.id) : id,
      mcVersion: base ? base.mcVersion : mcVersion,
      pluginName: base ? base.pluginName : null,
      ...(cyrus ? { cyrus } : {}),
    },
  });
  let attachments: CyrusAttachment[] = [];
  if (attachmentIds.length) {
    attachments = await claimUploads(user.id, id, attachmentIds).catch(() => []);
    if (attachments.length) await db.modBuild.update({ where: { id }, data: { cyrus: { ...(cyrus ?? {}), attachments } } });
  }
  // Cyrus reads the pasted images: their bytes go to the build service (0.4+), which puts
  // them in the build workspace for the model to look at. Already type-sniffed + size-capped.
  const images = (await Promise.all(attachments.map(async (a) => {
    const buf = await readAttachment(id, a).catch(() => null);
    return buf ? { name: a.name, type: a.type, data: buf.toString("base64") } : null;
  }))).filter((x): x is { name: string; type: string; data: string } => !!x);
  try {
    await svcCreate({
      id,
      prompt: row.prompt,
      mcVersion: row.mcVersion,
      ...(base ? { baseBuildId: base.id, changeRequest } : {}),
      ...(model ? { tier: model } : {}),
      ...(images.length ? { images } : {}),
    });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: msg, finishedAt: new Date() } });
    console.error("[modbuilder] create failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: base ? "modbuilder.change" : "modbuilder.build", detail: id } }).catch(() => {});
  const fresh = await db.modBuild.findUnique({ where: { id } });
  return NextResponse.json({ build: toView(fresh!) }, { status: 201 });
}
import { NextResponse } from "next/server";
import { svcCancel } from "@/lib/modbuilder/client";
import { isTerminal } from "@/lib/modbuilder/types";
import { NOT_FOUND, ownedBuild } from "../../../_lib";

export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  if (!isTerminal(o.build.status)) await svcCancel(o.build.id).catch(() => {});
  return NextResponse.json({ ok: true });
}
import { NextResponse } from "next/server";
import { syncBuild, toView } from "@/lib/modbuilder/store";
import { NOT_FOUND, ownedBuild } from "../../_lib";

export const dynamic = "force-dynamic";

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  let row = o.build;
  try { row = await syncBuild(row); } catch (e) { console.error("[modbuilder] sync", row.id, (e as Error).message); }
  return NextResponse.json({ build: toView(row) }, { headers: { "Cache-Control": "no-store" } });
}

