                    description:
                      partnerDiscountTier === "FIRST"
                        ? `Partner discount — 50% off your first purchase`
                        : `Partner discount — 10% off`,
                    qty: 1,
                    unitCents: -partnerDiscountCents,
                    amountCents: -partnerDiscountCents,
                  },
                ]
              : []),
          ],
        }),
      });
