          // The annual rate frozen at sale, so the renewal bills the SAME price the
          // order charged even if the admin retunes annual_discount_percent later.
          annualDiscountPct: quote.annualPct,
          // GRANDFATHER PROGRAM: the game plan's raw priceCents AT THE
          // MOMENT OF SALE, frozen so a later catalog price rise never
          // touches this server's renewal — see Server.grandfatheredRenewalCents's
          // own doc comment and renewal-charge.ts. Deliberately the raw
          // per-term-unit catalog rate, NOT `regularPlanCents` (this ORDER's
          // term total) — renewalCharge divides this by gamePlan.termMonths
          // itself, same as it does for the live gamePlan.priceCents.
