    data: {
      userId: user.id,
      action: "gameserver.order",
      detail: `${server.id} game=${quote.gameFamily} tier=${quote.planName} term=${quote.term}mo${sold ? " card" : " wallet"} region=${node?.region ?? placement.region} regionSource=${regionSource} node=${node?.name ?? (queueReason ? "queued" : "none")}${intent.region ? "" : " intentRegion=none"}${queueReason ? ` queued=${queueReason}` : ""}`,
