"use client";

import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import { CYRUS_GAMES, CYRUS_MODELS, cyrusModel, type CyrusModelId } from "@/lib/cyrus/models";
import { estimate, fmtUsd, modelAdvice } from "@/lib/cyrus/estimate";
import { CyIcon } from "./icons";
import { useVoice } from "./voice";

export type ComposerSubmit = { text: string; model: CyrusModelId; mcVersion: string; attachmentIds: string[] };
export type ComposerHandle = { focus: () => void; setText: (t: string, model?: CyrusModelId) => void; toggleVoice: () => void };
type Att = { key: string; name: string; url: string; status: "up" | "ok" | "err"; id?: string; error?: string };

const MAX_IMG = 4;

export const Composer = forwardRef<ComposerHandle, {
  kind: "new" | "change";
  placeholder: string;
  defaultModel: CyrusModelId;
  defaultVersion?: string;
  lockVersion?: string;
  disabledReason?: string | null;
  submitLabel: string;
  onSubmit: (s: ComposerSubmit) => Promise<string | null>;
  onActivity?: (a: { typing: boolean; listening: boolean; level: number }) => void;
  compact?: boolean;
}>(function Composer({ kind, placeholder, defaultModel, defaultVersion, lockVersion, disabledReason, submitLabel, onSubmit, onActivity, compact }, ref) {
  const [text, setText] = useState("");
  const [model, setModel] = useState<CyrusModelId>(defaultModel);
  const [version, setVersion] = useState(lockVersion || defaultVersion || CYRUS_GAMES[0].defaultVersion!);
  const [atts, setAtts] = useState<Att[]>([]);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [drag, setDrag] = useState(false);
  const [pop, setPop] = useState<null | "model" | "game">(null);
  const ta = useRef<HTMLTextAreaElement>(null);
  const fileIn = useRef<HTMLInputElement>(null);
  const typingT = useRef<number | undefined>(undefined);
  const [typing, setTyping] = useState(false);

  const voice = useVoice((said) => setText((t) => (t && !/\s$/.test(t) ? t + " " : t) + said));

  useEffect(() => setModel(defaultModel), [defaultModel]);
  useEffect(() => { if (lockVersion) setVersion(lockVersion); }, [lockVersion]);

  useImperativeHandle(ref, () => ({
    focus: () => ta.current?.focus(),
    setText: (t, m) => { setText(t); if (m) setModel(m); requestAnimationFrame(() => { ta.current?.focus(); autosize(); }); },
    toggleVoice: () => voice.toggle(),
  }));

  // Feed the nebula: typing bursts and the live voice level.
  useEffect(() => {
    if (!onActivity) return;
    if (!voice.listening) { onActivity({ typing, listening: false, level: 0 }); return; }
    let raf = 0;
    const tick = () => { onActivity({ typing, listening: true, level: voice.level.current }); raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [typing, voice.listening, onActivity, voice.level]);

  const autosize = () => {
    const el = ta.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, compact ? 200 : 320) + "px";
  };
  useEffect(autosize, [text, compact]);
  // Re-fit when the box changes width (layout switches between side-by-side and stacked).
  useEffect(() => {
    const el = ta.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    let w = el.clientWidth;
    const ro = new ResizeObserver(() => { if (el.clientWidth !== w) { w = el.clientWidth; autosize(); } });
    ro.observe(el);
    return () => ro.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [compact]);

  const attsRef = useRef<Att[]>([]);
  attsRef.current = atts;
  const addFiles = useCallback((files: File[]) => {
    const imgs = files.filter((f) => /^image\/(png|jpe?g|webp|gif)$/.test(f.type));
    if (!imgs.length) { if (files.length) setErr("Only PNG, JPG, WebP or GIF images can be attached."); return; }
    const room = MAX_IMG - attsRef.current.length;
    if (room <= 0) { setErr(`Up to ${MAX_IMG} images per request.`); return; }
    if (imgs.length > room) setErr(`Up to ${MAX_IMG} images per request.`);
    const add = imgs.slice(0, room).map((f) => ({ f, a: { key: Math.random().toString(36).slice(2), name: f.name || "pasted image", url: URL.createObjectURL(f), status: "up" as const } }));
    setAtts((cur) => [...cur, ...add.map((x) => x.a)]);
    for (const x of add) upload(x.a.key, x.f);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function upload(key: string, f: File) {
    if (f.size > 5 * 1024 * 1024) { setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "err", error: "Over 5 MB" } : a))); return; }
    const fd = new FormData();
    fd.append("file", f, f.name || "pasted.png");
    try {
      const r = await fetch("/api/mod-builder/uploads", { method: "POST", body: fd });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "Upload failed");
      setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "ok", id: j.upload.id } : a)));
    } catch (e) {
      setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "err", error: (e as Error).message } : a)));
    }
  }

  const est = useMemo(() => estimate(text, model, { change: kind === "change" }), [text, model, kind]);
  const advice = text.trim().length > 30 ? modelAdvice(est, model) : "ok";
  const minLen = kind === "change" ? 4 : 12;
  const uploading = atts.some((a) => a.status === "up");
  const canSend = !busy && !disabledReason && text.trim().length >= minLen && !uploading;

  async function submit() {
    if (!canSend) {
      if (text.trim().length < minLen && !disabledReason) setErr(kind === "change" ? "Describe the change in a few words." : "Tell Cyrus a bit more about the mod.");
      return;
    }
    if (voice.listening) voice.stop();
    setBusy(true); setErr(null);
    const e = await onSubmit({ text: text.trim(), model, mcVersion: version, attachmentIds: atts.filter((a) => a.status === "ok" && a.id).map((a) => a.id!) });
    setBusy(false);
    if (e) { setErr(e); return; }
    atts.forEach((a) => URL.revokeObjectURL(a.url));
    setText(""); setAtts([]);
  }

  const m = cyrusModel(model);
  const game = CYRUS_GAMES[0];
  const listening = voice.listening;

  return (
    <div
      className={`cy-composer ${compact ? "compact" : ""} ${listening ? "listening" : ""} ${drag ? "drag" : ""} ${busy ? "busy" : ""}`}
      onDragOver={(e) => { if (e.dataTransfer.types.includes("Files")) { e.preventDefault(); setDrag(true); } }}
      onDragLeave={(e) => { if (e.currentTarget === e.target) setDrag(false); }}
      onDrop={(e) => { e.preventDefault(); setDrag(false); addFiles(Array.from(e.dataTransfer.files)); }}
    >
      <div className="cy-composer-box">
      <div className="cy-rim" aria-hidden="true" />
      <div className="cy-composer-in">
        {atts.length > 0 && (
          <div className="cy-atts" aria-label="Attached images">
            {atts.map((a) => (
              <figure key={a.key} className={`cy-att ${a.status}`} title={a.error || a.name}>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={a.url} alt={a.name} />
                {a.status === "up" && <span className="cy-att-veil"><i className="cy-spin" /></span>}
                {a.status === "err" && <span className="cy-att-veil err"><CyIcon name="warn" size={14} /></span>}
                <button type="button" aria-label={`Remove ${a.name}`} onClick={() => { URL.revokeObjectURL(a.url); setAtts((c) => c.filter((x) => x.key !== a.key)); }}>
                  <CyIcon name="x" size={10} strokeWidth={2.2} />
                </button>
              </figure>
            ))}
            <span className="cy-att-note"><CyIcon name="eye" size={12} /> Cyrus looks at {atts.length === 1 ? "this image" : "these images"} while it plans: menus, colours, text, layouts.</span>
          </div>
        )}

        <div className="relative">
          <textarea
            ref={ta}
            value={text}
            rows={compact ? 1 : 3}
            maxLength={kind === "change" ? 2000 : 4000}
            placeholder={listening ? "" : placeholder}
            aria-label={kind === "change" ? "Describe a change" : "Describe your mod"}
            onChange={(e) => {
              setText(e.target.value); setErr(null);
              setTyping(true); window.clearTimeout(typingT.current);
              typingT.current = window.setTimeout(() => setTyping(false), 900);
            }}
            onPaste={(e) => { const f = Array.from(e.clipboardData.files); if (f.length) { e.preventDefault(); addFiles(f); } }}
            onKeyDown={(e) => {
              if (e.key === "Enter" && (e.metaKey || e.ctrlKey || (kind === "change" && !e.shiftKey))) { e.preventDefault(); submit(); }
            }}
          />
          {listening && (
            <div className="cy-listen" aria-live="polite">
              <VoiceWave level={voice.level} />
              <span className="cy-listen-t">{voice.interim ? <em>{voice.interim}</em> : <>Listening<span className="cy-ellipsis" /></>}</span>
            </div>
          )}
        </div>

        <div className="cy-bar">
          <div className="cy-bar-l">
            <button type="button" className="cy-tool" onClick={() => fileIn.current?.click()} aria-label="Attach images" title="Attach images (or paste / drop them)">
              <CyIcon name="image" size={17} />
            </button>
            <input ref={fileIn} type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple className="sr-only" tabIndex={-1}
                   onChange={(e) => { addFiles(Array.from(e.target.files || [])); e.target.value = ""; }} />
            <button type="button" className={`cy-tool cy-mic ${listening ? "on" : ""} ${voice.supported ? "" : "unsupported"}`} onClick={() => voice.toggle()}
                    aria-pressed={listening} aria-label={listening ? "Stop voice typing" : "Voice typing"} title={voice.supported ? "Talk to Cyrus (V)" : "Voice typing needs Chrome, Edge or Safari"}>
              <CyIcon name={listening ? "stop" : "mic"} size={17} />
            </button>
            <span className="cy-bar-sep" aria-hidden="true" />
            {!compact && (
              <Pop open={pop === "game"} onClose={() => setPop(null)}
                   trigger={
                     <button type="button" className="cy-pick" onClick={() => setPop(pop === "game" ? null : "game")} aria-haspopup="dialog" aria-expanded={pop === "game"}>
                       <span className="cy-pick-k">{game.name}</span><span className="cy-pick-v">{lockVersion ? `Paper ${lockVersion}` : `Paper ${version}`}</span><CyIcon name="chev" size={13} />
                     </button>
                   }>
                <GamePanel version={version} lock={!!lockVersion} onPick={(v) => { setVersion(v); setPop(null); }} />
              </Pop>
            )}
            <Pop open={pop === "model"} onClose={() => setPop(null)}
                 trigger={
                   <button type="button" className="cy-pick" onClick={() => setPop(pop === "model" ? null : "model")} aria-haspopup="dialog" aria-expanded={pop === "model"}>
                     <span className="cy-model-dot" style={{ background: m.hue }} />
                     <span className="cy-pick-k">{m.name}</span>
                     <Spend n={m.spend} />
                     <CyIcon name="chev" size={13} />
                   </button>
                 }>
              <ModelPanel model={model} recommended={text.trim().length > 30 ? est.recommended : null} onPick={(id) => { setModel(id); setPop(null); }} />
            </Pop>
          </div>
          <div className="cy-bar-r">
            {!compact && text.trim().length > 0 && (
              <span className="cy-est" title="Estimate from preview builds. You aren't charged during the preview.">
                <CyIcon name="clock" size={12} /> ~{est.minutes[0]}–{est.minutes[1]} min <span className="cy-est-sep">·</span> ≈ {fmtUsd(est.usd)} AI
              </span>
            )}
            <span className="cy-kbd-hint" aria-hidden="true">{kind === "change" ? "↵" : "⌘↵"}</span>
            <button type="button" className="cy-go" disabled={!canSend} onClick={submit} title={disabledReason || undefined}>
              {busy ? <i className="cy-spin" /> : <CyIcon name={kind === "change" ? "send" : "sparkle"} size={15} strokeWidth={1.9} />}
              <span>{busy ? "Starting…" : submitLabel}</span>
            </button>
          </div>
        </div>
      </div>
      </div>
      {(err || voice.error || disabledReason || advice !== "ok") && (
        <div className="cy-composer-msg" role={err || voice.error ? "alert" : undefined}>
          {err ? <span className="bad">{err}</span>
            : voice.error ? <span className="warn">{voice.error} <button type="button" onClick={voice.clearError}>Dismiss</button></span>
            : disabledReason ? <span className="mute">{disabledReason}</span>
            : advice === "under" ? <span className="hint">This sounds like a bigger mod. <button type="button" onClick={() => setModel(est.recommended)}>Use {cyrusModel(est.recommended).name}</button> for a better first try.</span>
            : <span className="hint">A small mod. <button type="button" onClick={() => setModel("katara")}>Katara</button> is fast for simple mods like this.</span>}
        </div>
      )}
    </div>
  );
});

function Spend({ n }: { n: number }) {
  return (
    <span className="cy-spend" aria-label={`Token spend ${n} of 3`}>
      {[1, 2, 3].map((i) => <i key={i} className={i <= n ? "on" : ""} />)}
    </span>
  );
}

function ModelPanel({ model, recommended, onPick }: { model: CyrusModelId; recommended: CyrusModelId | null; onPick: (m: CyrusModelId) => void }) {
  return (
    <div className="cy-panel" role="listbox" aria-label="Model">
      <div className="cy-panel-h">Choose a model</div>
      {CYRUS_MODELS.map((m) => (
        <button key={m.id} type="button" role="option" aria-selected={m.id === model} className={`cy-opt ${m.id === model ? "on" : ""}`} onClick={() => onPick(m.id)}>
          <span className="cy-opt-orb" style={{ ["--orb" as string]: m.hue }} />
          <span className="flex min-w-0 flex-1 flex-col gap-0.5 text-left">
            <span className="flex items-center gap-2">
              <b>{m.name}</b>
              <span className="cy-opt-blurb">{m.blurb}</span>
              {recommended === m.id && <span className="cy-tag">Suggested</span>}
            </span>
            <span className="cy-opt-sub">{m.bestFor}</span>
            <span className="cy-opt-cost"><Spend n={m.spend} /> {m.spendLabel}</span>
