/** Anchored popover; a bottom sheet on phones. */
function Pop({ open, onClose, trigger, children }: { open: boolean; onClose: () => void; trigger: React.ReactNode; children: React.ReactNode }) {
  const box = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!open) return;
    const down = (e: MouseEvent) => { if (box.current && !box.current.contains(e.target as Node)) onClose(); };
    const key = (e: KeyboardEvent) => { if (e.key === "Escape") { e.stopPropagation(); onClose(); } };
    document.addEventListener("mousedown", down);
    document.addEventListener("keydown", key, true);
    return () => { document.removeEventListener("mousedown", down); document.removeEventListener("keydown", key, true); };
  }, [open, onClose]);
  return (
    <span ref={box} className="cy-pop">
      {trigger}
      {open && (
        <>
          <span className="cy-pop-back" onClick={onClose} aria-hidden="true" />
          <span className="cy-pop-panel" role="dialog">{children}</span>
        </>
      )}
    </span>
  );
}

/** Aurora waveform: real mic level when available, a calm synthetic wave otherwise. */
function VoiceWave({ level }: { level: React.MutableRefObject<number> }) {
  const box = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const bars = Array.from(box.current?.children || []) as HTMLElement[];
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let raf = 0;
    const t0 = performance.now();
    const tick = (now: number) => {
      const t = (now - t0) / 1000;
      const lv = level.current;
      bars.forEach((b, i) => {
        const x = i / (bars.length - 1);
        const env = Math.sin(Math.PI * x);
        const wave = 0.5 + 0.5 * Math.sin(t * 7 + i * 0.75) * Math.sin(t * 2.3 + i * 0.31);
        const h = 0.14 + env * (0.18 + lv * 0.95) * (0.45 + wave * 0.75);
        b.style.transform = `scaleY(${Math.min(1, h).toFixed(3)})`;
      });
      if (!reduce) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [level]);
  return <span ref={box} className="cy-wave" aria-hidden="true">{Array.from({ length: 30 }, (_, i) => <i key={i} />)}</span>;
}

