// Cyrus plans + top-ups on Stripe. Server only; plain module (webhook, routes, worker).
//
// Plans are real Stripe Billing subscriptions (monthly). Every PAID plan invoice grants
// that month's tokens, keyed by the invoice id (`plan:<invoiceId>`), so tokens stack on
// each renewal and a webhook redelivery, the return redirect and the reconcile sweep can
// all run the same grant without double-granting. Top-ups are one-off Checkout payments
// keyed by the session id (`topup:<sessionId>`).
//
// ISOLATION FROM THE WALLET: our Checkout Sessions carry `cyrusUserId`, NEVER
// `nxeonUserId`. lib/fulfil-checkout.ts classifies a session without `nxeonUserId` as
// "unpaid" and does nothing, so the platform's wallet/order fulfilment can never mistake
// a Cyrus purchase for a wallet top-up (test/cyrus-tokens-stripe.test.ts pins this).
import type Stripe from "stripe";
import type { User } from "@prisma/client";
import { db } from "../../db";
import { stripe, stripeConfigured, stripePublishableKey, createCheckoutSessionLogged, CUSTOM_CHECKOUT_UI_MODE, EMBEDDED_REQUEST_OPTS } from "../../stripe";
import { loadTokenConfig, PLAN_TIERS, type PlanTier, type TokenConfig } from "./config";
import { PLAN_LOOKUP_KEY, planInvoiceTokens, rolloverExcess, tierFromLookupKey, TIER_RANK, topupTokens, validTopupCents, fmt } from "./economy";
import { capLotExpiry, creditTokens, revokeTokens, trimSource } from "./ledger";

const DAY = 86_400_000;
type StripeLike = Stripe;
let override: StripeLike | null = null;
/** Tests inject a fake client (no network). */
export function setCyrusStripeForTests(s: StripeLike | null) { override = s; priceCache = null; }
const sc = (): StripeLike => override ?? stripe();
const configured = () => !!override || stripeConfigured();
const appBase = () => process.env.APP_URL ?? "http://localhost:3000";
const ts = (n: number | null | undefined) => (n ? new Date(n * 1000) : null);
const idOf = (x: string | { id: string } | null | undefined) => (typeof x === "string" ? x : x?.id ?? null);

// ---------------------------------------------------------------------------
// Prices
// ---------------------------------------------------------------------------

export type PlanPrice = { tier: PlanTier; id: string; unitAmount: number | null; currency: string; livemode: boolean };
let priceCache: { at: number; key: string; prices: Record<PlanTier, PlanPrice | null> } | null = null;

/** The three plan prices: Setting override ids, else the price with lookup_key cyrus_plan_<tier>_v1. */
export async function planPrices(cfg?: TokenConfig): Promise<Record<PlanTier, PlanPrice | null>> {
  const c = cfg ?? (await loadTokenConfig());
  const empty = { katara: null, saka: null, all: null } as Record<PlanTier, PlanPrice | null>;
  if (!configured()) return empty;
  const key = JSON.stringify(c.plan.priceIds);
  if (priceCache && priceCache.key === key && Date.now() - priceCache.at < 10 * 60_000) return priceCache.prices;
  const out = { ...empty };
  const toPlan = (tier: PlanTier, p: Stripe.Price): PlanPrice => ({ tier, id: p.id, unitAmount: p.unit_amount, currency: p.currency, livemode: p.livemode });
  try {
    const listed = await sc().prices.list({ lookup_keys: PLAN_TIERS.map(PLAN_LOOKUP_KEY), active: true, limit: 10 });
    for (const p of listed.data) { const t = tierFromLookupKey(p.lookup_key); if (t && !out[t]) out[t] = toPlan(t, p); }
    for (const t of PLAN_TIERS) {
      const id = c.plan.priceIds[t];
      if (id) out[t] = toPlan(t, await sc().prices.retrieve(id));
    }
  } catch (e) {
    console.error("[cyrus-tokens] price lookup failed", (e as Error).message);
    return empty;
  }
  priceCache = { at: Date.now(), key, prices: out };
  return out;
}

export async function tierOfPrice(price: string | Stripe.Price | null | undefined, cfg?: TokenConfig): Promise<PlanTier | null> {
  if (!price) return null;
  if (typeof price !== "string") {
    const t = tierFromLookupKey(price.lookup_key) ?? (price.metadata?.cyrus_tier as PlanTier | undefined);
    if (t && (PLAN_TIERS as readonly string[]).includes(t)) return t as PlanTier;
  }
  const id = idOf(price);
  const prices = await planPrices(cfg);
  return PLAN_TIERS.find((t) => prices[t]?.id === id) ?? null;
}

// ---------------------------------------------------------------------------
// Checkout (plan subscription / one-off top-up)
// ---------------------------------------------------------------------------

export type CheckoutOpen = { ok: true; clientSecret: string; publishableKey: string } | { ok: false; error: string };

const ACTIVE = ["active", "trialing", "past_due", "incomplete"];

async function customerFor(user: User): Promise<string> {
  if (override) {
    if (user.stripeCustomerId) return user.stripeCustomerId;
    const c = await sc().customers.create({ email: user.email, metadata: { nxeonUserId: user.id } });
    await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: c.id } });
    return c.id;
  }
  const { ensureStripeCustomer } = await import("../../stripe-cards");
  return ensureStripeCustomer(user);
}

export async function openPlanCheckout(user: User, tier: PlanTier): Promise<CheckoutOpen> {
  if (!configured()) return { ok: false, error: "Payments aren't available right now." };
  const cfg = await loadTokenConfig();
  const price = (await planPrices(cfg))[tier];
  if (!price) return { ok: false, error: "Plans aren't set up yet. Please try again later." };
  const cur = await db.cyrusPlan.findUnique({ where: { userId: user.id } });
  if (cur && ACTIVE.includes(cur.status) && !cur.endedAt) return { ok: false, error: "You already have a plan. Change it from your plan instead." };
  const customer = await customerFor(user);
  const session = await (override ? sc().checkout.sessions.create.bind(sc().checkout.sessions) : createCheckoutSessionLogged)({
    mode: "subscription",
    customer,
    ui_mode: CUSTOM_CHECKOUT_UI_MODE,
    payment_method_types: ["card"],
    line_items: [{ price: price.id, quantity: 1 }],
    return_url: `${appBase()}/api/cyrus/tokens/return?session_id={CHECKOUT_SESSION_ID}`,
    metadata: { cyrusUserId: user.id, cyrusKind: "plan", cyrusTier: tier },
    subscription_data: { metadata: { cyrusUserId: user.id, cyrusTier: tier }, description: `Cyrus ${tier === "all" ? "All models" : tier[0].toUpperCase() + tier.slice(1)} plan` },
  }, EMBEDDED_REQUEST_OPTS);
  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : { ok: false, error: "Couldn't open checkout." };
}

export async function openTopupCheckout(user: User, cents: number): Promise<CheckoutOpen> {
  if (!configured()) return { ok: false, error: "Payments aren't available right now." };
  const cfg = await loadTokenConfig();
  if (!cfg.topup.enabled) return { ok: false, error: "Top-ups aren't available right now." };
  if (!validTopupCents(cents, cfg)) return { ok: false, error: `Pick an amount from $${(cfg.topup.minCents / 100).toFixed(0)} to $${(cfg.topup.maxCents / 100).toFixed(0)}.` };
  if (cfg.topup.requiresPaid) {
    const paid = await db.server.count({ where: { userId: user.id, isFree: false, gamePlanId: { not: null } } }) + await db.cyrusPlan.count({ where: { userId: user.id } });
    if (!paid) return { ok: false, error: "Top-ups are for customers with a game server or a Cyrus plan." };
  }
  const tokens = topupTokens(cents, cfg);
  const customer = await customerFor(user);
  const md = { cyrusUserId: user.id, cyrusKind: "topup", cyrusTokens: String(tokens), cyrusCents: String(cents) };
  const session = await (override ? sc().checkout.sessions.create.bind(sc().checkout.sessions) : createCheckoutSessionLogged)({
    mode: "payment",
    customer,
    ui_mode: CUSTOM_CHECKOUT_UI_MODE,
    payment_method_types: ["card"],
    line_items: [{ price_data: { currency: "usd", unit_amount: cents, product_data: { name: `${fmt(tokens)} Cyrus tokens` } }, quantity: 1 }],
    return_url: `${appBase()}/api/cyrus/tokens/return?session_id={CHECKOUT_SESSION_ID}`,
    metadata: md,
    payment_intent_data: { metadata: md, description: `${fmt(tokens)} Cyrus tokens` },
  }, EMBEDDED_REQUEST_OPTS);
  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : { ok: false, error: "Couldn't open checkout." };
}

/** A paid top-up session -> tokens (idempotent per session). Returns tokens granted (0 if replay/unpaid). */
export async function fulfilTopup(session: Stripe.Checkout.Session): Promise<number> {
  const md = session.metadata ?? {};
  if (md.cyrusKind !== "topup" || !md.cyrusUserId || session.payment_status !== "paid" || session.mode !== "payment") return 0;
  const cfg = await loadTokenConfig();
  const paidCents = session.amount_total ?? 0;
  // The amount actually paid decides the tokens; the metadata figure is only a cap.
  const tokens = Math.min(Number(md.cyrusTokens) || 0, topupTokens(paidCents, cfg));
  const r = await creditTokens({
    userId: md.cyrusUserId,
    amount: tokens,
    kind: "purchase",
    source: "topup",
    sourceRef: session.id,
    idemKey: `topup:${session.id}`,
    expiresAt: new Date(Date.now() + cfg.topup.expiryDays * DAY),
    note: `Top-up $${(paidCents / 100).toFixed(2)}`,
    meta: { paidCents, paymentIntent: idOf(session.payment_intent as string | { id: string } | null), livemode: session.livemode },
  });
  return r.created ? r.amount : 0;
}

/** The Checkout return leg (and the webhook's checkout events). */
export async function fulfilCyrusSession(sessionOrId: string | Stripe.Checkout.Session): Promise<{ kind: "plan" | "topup" | "none"; userId: string | null; tokens: number }> {
  const session = typeof sessionOrId === "string" ? await sc().checkout.sessions.retrieve(sessionOrId) : sessionOrId;
  const md = session.metadata ?? {};
  if (!md.cyrusUserId) return { kind: "none", userId: null, tokens: 0 };
  if (md.cyrusKind === "topup") return { kind: "topup", userId: md.cyrusUserId, tokens: await fulfilTopup(session) };
  if (md.cyrusKind === "plan" && session.subscription) {
    const before = await db.cyrusTokenLedger.aggregate({ where: { userId: md.cyrusUserId, source: "plan", kind: "purchase" }, _sum: { delta: true } });
    await reconcileSubscription(idOf(session.subscription as string | { id: string })!);
    const after = await db.cyrusTokenLedger.aggregate({ where: { userId: md.cyrusUserId, source: "plan", kind: "purchase" }, _sum: { delta: true } });
    return { kind: "plan", userId: md.cyrusUserId, tokens: (after._sum.delta ?? 0) - (before._sum.delta ?? 0) };
  }
  return { kind: "none", userId: md.cyrusUserId, tokens: 0 };
}

// ---------------------------------------------------------------------------
// Subscriptions + invoices
// ---------------------------------------------------------------------------

function subUserId(sub: Stripe.Subscription): string | null {
  return sub.metadata?.cyrusUserId || null;
}

function subPeriod(sub: Stripe.Subscription): { start: Date | null; end: Date | null } {
  const it = sub.items?.data?.[0] as (Stripe.SubscriptionItem & { current_period_start?: number; current_period_end?: number }) | undefined;
  const legacy = sub as unknown as { current_period_start?: number; current_period_end?: number };
  return { start: ts(it?.current_period_start ?? legacy.current_period_start), end: ts(it?.current_period_end ?? legacy.current_period_end) };
}

/** Mirror a Cyrus subscription into CyrusPlan. Returns the row (null if not ours). */
export async function syncSubscription(sub: Stripe.Subscription): Promise<{ userId: string } | null> {
  const userId = subUserId(sub);
  if (!userId) return null;
  const cfg = await loadTokenConfig();
  const priceTier = (await tierOfPrice(sub.items?.data?.[0]?.price, cfg)) ?? (sub.metadata?.cyrusTier as PlanTier) ?? "katara";
  const { start, end } = subPeriod(sub);
  const cur = await db.cyrusPlan.findUnique({ where: { userId } });
  const sameSub = cur?.stripeSubscriptionId === sub.id;
  // A newer subscription replaces an old ended one; an old subscription's late event never
  // overwrites a newer live one.
  if (cur && !sameSub && ACTIVE.includes(cur.status) && !cur.endedAt && !ACTIVE.includes(sub.status)) return { userId };
  const endedAt = ts(sub.ended_at);
  const data = {
    stripeCustomerId: idOf(sub.customer as string | { id: string })!,
    stripeSubscriptionId: sub.id,
    priceTier,
    status: sub.status,
    currentPeriodStart: start,
    currentPeriodEnd: end,
    cancelAtPeriodEnd: !!sub.cancel_at_period_end,
    endedAt,
    livemode: sub.livemode,
    lastSyncAt: new Date(),
  };
  // `tier` (the paid entitlement) only ever comes from a paid invoice; a brand-new row
  // starts at the price's tier but has no period until the first invoice is paid.
  await db.cyrusPlan.upsert({
    where: { userId },
    create: { userId, tier: priceTier, ...data },
    update: sameSub ? data : { tier: priceTier, ...data },
  });
  if (sub.status === "canceled" || sub.status === "incomplete_expired" || endedAt) {
    const until = new Date((end ?? endedAt ?? new Date()).getTime() + cfg.plan.cancelGraceDays * DAY);
    await capLotExpiry(userId, "plan", until);
  }
  return { userId };
}

type InvoiceLine = { amount: number; price: string | Stripe.Price | null; periodEnd: Date | null; proration: boolean };

function invoiceLines(inv: Stripe.Invoice): InvoiceLine[] {
  return (inv.lines?.data ?? []).map((l) => {
    const anyL = l as unknown as { pricing?: { price_details?: { price?: string | Stripe.Price } }; price?: Stripe.Price; proration?: boolean; parent?: { subscription_item_details?: { proration?: boolean } } };
    return {
      amount: l.amount,
      price: anyL.pricing?.price_details?.price ?? anyL.price ?? null,
      periodEnd: ts(l.period?.end),
      proration: !!(anyL.proration ?? anyL.parent?.subscription_item_details?.proration),
    };
  });
}

function invoiceSubscriptionId(inv: Stripe.Invoice): string | null {
  const p = (inv as unknown as { parent?: { subscription_details?: { subscription?: string | { id: string } } }; subscription?: string | { id: string } });
  return idOf(p.parent?.subscription_details?.subscription ?? p.subscription ?? null);
}

function invoiceMetaUser(inv: Stripe.Invoice): string | null {
  const p = inv as unknown as { parent?: { subscription_details?: { metadata?: Record<string, string> } }; subscription_details?: { metadata?: Record<string, string> } };
  return p.parent?.subscription_details?.metadata?.cyrusUserId ?? p.subscription_details?.metadata?.cyrusUserId ?? null;
}

async function invoicePaymentIntent(inv: Stripe.Invoice): Promise<string | null> {
  const p = (inv as unknown as { payments?: { data?: { payment?: { payment_intent?: string | { id: string } } }[] }; payment_intent?: string | { id: string } });
  const direct = idOf(p.payments?.data?.[0]?.payment?.payment_intent ?? p.payment_intent ?? null);
  if (direct) return direct;
  try {
    const list = await (sc() as unknown as { invoicePayments: { list: (q: { invoice: string; limit: number }) => Promise<{ data: { payment?: { payment_intent?: string | { id: string } } }[] }> } }).invoicePayments.list({ invoice: inv.id!, limit: 3 });
    return idOf(list.data.find((x) => x.payment?.payment_intent)?.payment?.payment_intent ?? null);
  } catch { return null; }
}

/**
 * Grant the tokens of one PAID Cyrus plan invoice (idempotent per invoice) and move the
 * paid entitlement to the invoice's tier. Returns tokens newly granted.
 */
export async function grantPlanInvoice(inv: Stripe.Invoice, userIdHint?: string | null): Promise<number> {
  if (inv.status !== "paid" || !inv.id) return 0;
  const subId = invoiceSubscriptionId(inv);
  const plan = subId ? await db.cyrusPlan.findUnique({ where: { stripeSubscriptionId: subId } }) : null;
  const userId = invoiceMetaUser(inv) ?? plan?.userId ?? userIdHint ?? null;
  if (!userId) return 0;
  const cfg = await loadTokenConfig();
  const lines = invoiceLines(inv);
  let tier: PlanTier | null = null;
  let periodEnd: Date | null = null;
  for (const l of lines) {
    if (l.amount <= 0) continue;
    const t = await tierOfPrice(l.price, cfg);
    if (t && (!tier || TIER_RANK[t] > TIER_RANK[tier])) { tier = t; periodEnd = l.periodEnd; }
  }
  if (!tier) return 0;
  const tokens = planInvoiceTokens({ billingReason: inv.billing_reason ?? null, amountPaidCents: inv.amount_paid, tier }, cfg);
  const pi = await invoicePaymentIntent(inv);
  const r = await creditTokens({
    userId,
    amount: tokens,
    kind: "purchase",
    source: "plan",
    sourceRef: inv.id,
    idemKey: `plan:${inv.id}`,
    expiresAt: new Date(Date.now() + cfg.plan.lotExpiryDays * DAY),
    note: `${tier === "all" ? "All models" : tier[0].toUpperCase() + tier.slice(1)} plan · ${inv.billing_reason === "subscription_cycle" ? "renewal" : inv.billing_reason === "subscription_update" ? "upgrade" : "first month"}`,
    meta: { invoice: inv.id, billingReason: inv.billing_reason ?? null, amountPaid: inv.amount_paid, tier, paymentIntent: pi, subscription: subId, livemode: inv.livemode },
  });
  // Entitlement follows the money: the tier of the latest paid invoice.
  if (plan) {
    const data: { tier: PlanTier; currentPeriodEnd?: Date } = { tier };
    if (periodEnd && (!plan.currentPeriodEnd || periodEnd > plan.currentPeriodEnd) && inv.billing_reason !== "subscription_update") data.currentPeriodEnd = periodEnd;
    if (inv.billing_reason === "subscription_update" && TIER_RANK[tier] < TIER_RANK[(plan.tier as PlanTier) ?? "katara"]) delete (data as { tier?: PlanTier }).tier;
    await db.cyrusPlan.update({ where: { userId: plan.userId }, data });
  }
  // Rollover cap: plan tokens stack up to N months of the CURRENT plan; the oldest go first.
  const agg = await db.cyrusTokenLot.aggregate({ where: { userId, source: "plan", remaining: { gt: 0 } }, _sum: { remaining: true } });
  if (rolloverExcess(agg._sum.remaining ?? 0, tier, cfg) > 0) {
    await trimSource({ userId, source: "plan", keep: Math.round(cfg.plan.rolloverMonths * cfg.plan.tokens[tier]), idemKey: `rollover:${inv.id}` });
  }
  return r.created ? r.amount : 0;
}

/** Pull a subscription and its paid invoices from Stripe and apply everything missing. */
export async function reconcileSubscription(subId: string): Promise<{ userId: string | null; granted: number }> {
  const sub = await sc().subscriptions.retrieve(subId, { expand: ["items.data.price"] });
  const s = await syncSubscription(sub);
  if (!s) return { userId: null, granted: 0 };
  const invs = await sc().invoices.list({ subscription: subId, status: "paid", limit: 24, expand: ["data.lines.data.pricing.price_details.price"] } as Stripe.InvoiceListParams);
  let granted = 0;
  for (const inv of [...invs.data].reverse()) granted += await grantPlanInvoice(inv, s.userId);
  // grantPlanInvoice can move `tier`; re-sync status/period last.
  await syncSubscription(await sc().subscriptions.retrieve(subId, { expand: ["items.data.price"] }));
  return { userId: s.userId, granted };
}

/** Reconcile one account's plan if it hasn't been synced recently (page loads call this). */
export async function maybeReconcileUser(userId: string, maxAgeMs = 5 * 60_000): Promise<void> {
  if (!configured()) return;
  const p = await db.cyrusPlan.findUnique({ where: { userId } });
  if (!p || (p.lastSyncAt && Date.now() - p.lastSyncAt.getTime() < maxAgeMs)) return;
  if (p.endedAt && p.lastSyncAt && p.lastSyncAt > p.endedAt) return;
  try { await reconcileSubscription(p.stripeSubscriptionId); } catch (e) { console.error("[cyrus-tokens] reconcile failed", userId, (e as Error).message); }
}

// ---------------------------------------------------------------------------
// Plan changes
// ---------------------------------------------------------------------------

export async function changePlan(user: User, tier: PlanTier): Promise<{ ok: true; message: string } | { ok: false; error: string }> {
  const p = await db.cyrusPlan.findUnique({ where: { userId: user.id } });
  if (!p || !ACTIVE.includes(p.status) || p.endedAt) return { ok: false, error: "You don't have an active plan." };
  if (p.priceTier === tier && !p.cancelAtPeriodEnd) return { ok: false, error: "That's already your plan." };
  const price = (await planPrices())[tier];
  if (!price) return { ok: false, error: "Plans aren't set up yet." };
  const sub = await sc().subscriptions.retrieve(p.stripeSubscriptionId);
  const item = sub.items.data[0];
  const up = TIER_RANK[tier] > TIER_RANK[p.tier as PlanTier];
  try {
    await sc().subscriptions.update(sub.id, {
      items: [{ id: item.id, price: price.id }],
      // Upgrade: charge the prorated difference now, unlock now, grant tokens for what was paid.
      // Downgrade: no refund; the cheaper price (and tier) starts with the next renewal.
      proration_behavior: up ? "always_invoice" : "none",
      ...(up ? { payment_behavior: "error_if_incomplete" as const } : {}),
      cancel_at_period_end: false,
      metadata: { ...sub.metadata, cyrusTier: tier },
    });
  } catch (e) {
    return { ok: false, error: (e as { message?: string }).message?.includes("authentication") ? "Your bank needs to confirm this payment. Please try again." : "We couldn't change your plan. Your card was not charged." };
  }
  await reconcileSubscription(sub.id);
  return { ok: true, message: up ? "Upgraded. Your new models are unlocked." : "Done. Your plan changes at your next renewal; you keep your current models until then." };
}

export async function setCancelAtPeriodEnd(user: User, cancel: boolean): Promise<{ ok: true } | { ok: false; error: string }> {
  const p = await db.cyrusPlan.findUnique({ where: { userId: user.id } });
  if (!p || !ACTIVE.includes(p.status) || p.endedAt) return { ok: false, error: "You don't have an active plan." };
  await sc().subscriptions.update(p.stripeSubscriptionId, { cancel_at_period_end: cancel });
  await reconcileSubscription(p.stripeSubscriptionId);
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Refunds
// ---------------------------------------------------------------------------

/**
 * A refunded payment takes back the UNSPENT tokens it bought, in proportion to the amount
 * refunded (from that purchase's own lot only; tokens already spent stay spent).
 */
export async function handleRefundedCharge(ch: Stripe.Charge): Promise<number> {
  const pi = idOf(ch.payment_intent as string | { id: string } | null);
  if (!pi || !ch.amount || !ch.amount_refunded) return 0;
  const rows = await db.cyrusTokenLedger.findMany({ where: { kind: "purchase", meta: { path: ["paymentIntent"], equals: pi } } });
  let total = 0;
  for (const row of rows) {
    if (!row.lotId || row.delta <= 0) continue;
    const want = Math.round(row.delta * Math.min(1, ch.amount_refunded / ch.amount));
    const prior = await db.cyrusTokenLedger.findMany({ where: { kind: "revoke", sourceRef: row.id } });
    const already = prior.reduce((a, x) => a + ((x.meta as { requested?: number } | null)?.requested ?? 0), 0);
    if (want - already <= 0) continue;
    const r = await revokeTokens({ userId: row.userId, amount: want - already, lotIds: [row.lotId], idemKey: `refund:${ch.id}:${ch.amount_refunded}:${row.id}`, note: `Refund ${ch.id}`, meta: { charge: ch.id, refunded: ch.amount_refunded } });
    if (r.created) {
      await db.cyrusTokenLedger.updateMany({ where: { idemKey: `refund:${ch.id}:${ch.amount_refunded}:${row.id}` }, data: { sourceRef: row.id } });
      total += r.revoked;
    }
  }
  return total;
}

// ---------------------------------------------------------------------------
// Webhook entry
// ---------------------------------------------------------------------------

/**
 * Called by app/api/stripe/webhook for EVERY verified event. Returns true when the event
 * was a Cyrus one. Re-fetches the object from Stripe before acting (the event body is a
 * hint, not the truth), so a replayed or out-of-order event applies the current state.
 */
export async function handleCyrusStripeEvent(event: Stripe.Event): Promise<boolean> {
  const obj = event.data.object as unknown as Record<string, unknown> & { id: string; metadata?: Record<string, string> };
  switch (event.type) {
    case "checkout.session.completed":
    case "checkout.session.async_payment_succeeded": {
      if (!obj.metadata?.cyrusUserId) return false;
      await fulfilCyrusSession(obj.id);
      return true;
    }
    case "invoice.paid":
    case "invoice.payment_succeeded": {
      const inv = obj as unknown as Stripe.Invoice;
      const subId = invoiceSubscriptionId(inv);
      const ours = !!invoiceMetaUser(inv) || (subId ? !!(await db.cyrusPlan.findUnique({ where: { stripeSubscriptionId: subId }, select: { userId: true } })) : false);
      if (!ours || !subId) return false;
      await reconcileSubscription(subId);
      return true;
    }
    case "customer.subscription.created":
    case "customer.subscription.updated":
    case "customer.subscription.deleted": {
      if (!obj.metadata?.cyrusUserId) return false;
      await reconcileSubscription(obj.id);
      return true;
    }
    case "charge.refunded": {
      const n = await handleRefundedCharge(obj as unknown as Stripe.Charge);
      return n > 0;
    }
    default:
      return false;
  }
}

