// What the Cyrus client sees about tokens. Never includes USD cost per token or any
// model family name. The client types are re-exported for components/cyrus-tokens/*.
import type { CyrusModelId } from "../models";
import type { PlanTier, ReserveTable, TokenTier } from "./config";

export type TokenPlanOffer = { tier: PlanTier; name: string; priceCents: number; tokens: number; models: CyrusModelId[]; purchasable: boolean };

export type TokenState = {
  /** false = this account is outside the token economy (nothing to show). */
  active: boolean;
  enforce: boolean;
  balance: number;
  reserved: number;
  available: number;
  lowBalance: number;
  nextExpiry: { at: string; amount: number } | null;
  tier: TokenTier;
  models: CyrusModelId[];
  plan: { tier: PlanTier; priceTier: PlanTier; status: string; currentPeriodEnd: string | null; cancelAtPeriodEnd: boolean; active: boolean } | null;
  plans: TokenPlanOffer[];
  topup: { enabled: boolean; minCents: number; maxCents: number; tokensPerUsd: number };
  reserve: ReserveTable;
  payments: boolean;
};

export type TokenHistoryRow = {
  id: string;
  kind: string;
  delta: number;
  hold: number | null;
  at: string;
  source: string | null;
  model: string | null;
  buildId: string | null;
  label: string;
};

export type TokenHistory = { rows: TokenHistoryRow[]; more: boolean };

const SOURCE_LABEL: Record<string, string> = {
  server_initial: "Game server purchase",
  server_renewal: "Game server renewal",
  plan: "Cyrus plan",
  topup: "Token top-up",
  admin: "Added by Nxeon",
  refund: "Refund",
};

/** Plain-English line for one ledger row (no internal reasons, costs or models families). */
export function historyLabel(r: { kind: string; source: string | null; note: string | null; meta: unknown }): string {
  const m = (r.meta ?? {}) as { hold?: number; released?: number; writeoff?: number };
  switch (r.kind) {
    case "grant":
    case "purchase":
      return (r.kind === "purchase" && r.note) ? r.note : SOURCE_LABEL[r.source ?? ""] ?? "Tokens added";
    case "refund": return r.note || "Tokens returned";
    case "reserve": return "Held for a build";
    case "spend":
      return r.note === "refused" ? "Build declined (unsafe request)" : r.note === "cancelled" ? "Build stopped" : r.note?.startsWith("failed") ? "Build didn't finish" : "Build";
    case "release": return r.note === "not_started" ? "Build didn't start, tokens returned" : "Build didn't finish, tokens returned";
    case "expire": return r.note === "rollover cap" ? "Oldest plan tokens expired (rollover limit)" : "Tokens expired";
    case "revoke": return r.note?.startsWith("Refund") ? "Payment refunded" : "Tokens removed by Nxeon";
    default: void m; return "Tokens";
  }
}

