import { NextResponse } from "next/server";
import { currentUser, realUser } from "@/lib/auth";
import { loadTokenConfig } from "@/lib/cyrus/tokens/config";
import { tokensActiveFor } from "@/lib/cyrus/tokens/access";
import { checkoutLine } from "@/lib/cyrus/tokens/economy";

export const dynamic = "force-dynamic";
const NONE = () => NextResponse.json({ line: null }, { status: 404, headers: { "Cache-Control": "no-store", "x-robots-tag": "noindex" } });

/**
 * The game-checkout line "Includes N Cyrus tokens (+M every renewal) · Beta, Minecraft Java".
 * GATED: until cyrus_tok_live, only private-preview accounts get a line (and never while
 * impersonating); everyone else gets a plain 404 and the checkout renders nothing.
 */
export async function GET(req: Request) {
  const [user, real] = await Promise.all([currentUser(), realUser()]);
  if (!user || !real || user.id !== real.id) return NONE();
  const cfg = await loadTokenConfig();
  if (!cfg.checkoutLine || !(await tokensActiveFor(user, cfg))) return NONE();
  const url = new URL(req.url);
  const monthlyCents = Math.round(Number(url.searchParams.get("monthlyCents")));
  const termMonths = Math.round(Number(url.searchParams.get("termMonths") || 1));
  if (!(monthlyCents > 0 && monthlyCents < 10_000_00) || !(termMonths >= 1 && termMonths <= 36)) return NONE();
  const l = checkoutLine(monthlyCents, termMonths, cfg);
  return l ? NextResponse.json({ line: l }, { headers: { "Cache-Control": "no-store" } }) : NONE();
}
EOF
