 *
 * Opt-in and fail-closed: runs only when CYRUS_TOKENS_TEST_DATABASE_URL is set, equals
 * DATABASE_URL, points at localhost and the database name ends in `_cyrustokens` (the
 * agent DB `nxeon_agt_cyrustokens`, schema pushed with `npx prisma db push`).
 *
 *   DATABASE_URL=postgresql://...@localhost:5432/nxeon_agt_cyrustokens \
 *   CYRUS_TOKENS_TEST_DATABASE_URL=$DATABASE_URL npx tsx --test test/cyrus-tokens-ledger-db.test.ts
 */
const url = process.env.CYRUS_TOKENS_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@(localhost|127\.0\.0\.1)(:\d+)?\/[a-z_]*_cyrustokens$/.test(url);
const skip = safe ? false : "set CYRUS_TOKENS_TEST_DATABASE_URL (= DATABASE_URL, a throwaway *_cyrustokens db) to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let L: typeof import("../lib/cyrus/tokens/ledger.ts");
let G: typeof import("../lib/cyrus/tokens/grants.ts");
let B: typeof import("../lib/cyrus/tokens/builds.ts");
let S: typeof import("../lib/cyrus/tokens/billing.ts");
let C: typeof import("../lib/cyrus/tokens/config.ts");
const DAY = 86_400_000;
const uniq = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
const users: string[] = [];

async function mkUser(opts: { email?: string; createdAt?: Date } = {}) {
  const u = await db.user.create({ data: { email: opts.email ?? `cyt-${uniq()}@example.test`, passwordHash: "x", name: "Cyrus Token Test", ...(opts.createdAt ? { createdAt: opts.createdAt } : {}) } });
  users.push(u.id);
  return u;
}
const bal = async (userId: string) => (await L.tokenSummary(userId)).balance;

before(async () => {
  if (!safe) return;
  db = (await import("../lib/db.ts")).db;
  L = await import("../lib/cyrus/tokens/ledger.ts");
  G = await import("../lib/cyrus/tokens/grants.ts");
  B = await import("../lib/cyrus/tokens/builds.ts");
  S = await import("../lib/cyrus/tokens/billing.ts");
  C = await import("../lib/cyrus/tokens/config.ts");
  await db.setting.upsert({ where: { key: "cyrus_tok_live" }, update: { value: "true" }, create: { key: "cyrus_tok_live", value: "true" } });
  C.clearTokenConfigCache();
});

after(async () => {
  if (!safe) return;
  await db.setting.deleteMany({ where: { key: { startsWith: "cyrus_tok_" } } });
  for (const t of ["cyrusTokenLedger", "cyrusTokenLot", "cyrusTokenReservation", "cyrusTokenAccount", "cyrusPlan"] as const) {
    await (db[t] as unknown as { deleteMany: (a: unknown) => Promise<unknown> }).deleteMany({ where: { userId: { in: users } } });
  }
  await db.modBuild.deleteMany({ where: { userId: { in: users } } });
  await db.user.deleteMany({ where: { id: { in: users } } });
  S.setCyrusStripeForTests(null);
  await db.$disconnect();
});

describe("ledger: idempotent credits", { skip }, () => {
  it("the same idemKey credits once, even when fired concurrently", async () => {
    const u = await mkUser();
    const key = `t:${uniq()}`;
    const rs = await Promise.all(Array.from({ length: 6 }, () => L.creditTokens({ userId: u.id, amount: 250, kind: "grant", source: "admin", idemKey: key })));
    assert.equal(rs.filter((r) => r.created).length, 1);
    assert.equal(await bal(u.id), 250);
    assert.equal(await db.cyrusTokenLot.count({ where: { userId: u.id } }), 1);
    assert.equal(await db.cyrusTokenLedger.count({ where: { idemKey: key } }), 1);
