// ---------------------------------------------------------------------------
// Stripe webhooks with a fake client (replays, stacking, upgrade, refund)
// ---------------------------------------------------------------------------

type Inv = Record<string, unknown>;
function fakeStripe(state: { subs: Record<string, Record<string, unknown>>; invoices: Inv[]; sessions: Record<string, Record<string, unknown>> }) {
  const price = (tier: string) => ({ id: `price_${tier}`, lookup_key: `cyrus_plan_${tier}_v1`, unit_amount: { katara: 499, saka: 1999, all: 4999 }[tier], currency: "usd", livemode: false, metadata: {} });
  return {
    prices: {
      list: async () => ({ data: ["katara", "saka", "all"].map(price) }),
      retrieve: async (id: string) => price(id.replace("price_", "")),
    },
    subscriptions: { retrieve: async (id: string) => state.subs[id], update: async () => ({}) },
    invoices: { list: async (q: { subscription: string }) => ({ data: state.invoices.filter((i) => (i.parent as { subscription_details: { subscription: string } }).subscription_details.subscription === q.subscription).slice().reverse() }) },
    invoicePayments: { list: async () => ({ data: [] }) },
    checkout: { sessions: { retrieve: async (id: string) => state.sessions[id], create: async () => ({ client_secret: "cs_secret" }) } },
    customers: { create: async () => ({ id: `cus_${uniq()}` }) },
  };
}
const sub = (id: string, userId: string, tier: string, status = "active", end = Date.now() + 30 * DAY) => ({
  id, status, customer: "cus_x", livemode: false, cancel_at_period_end: false, ended_at: null,
  metadata: { cyrusUserId: userId, cyrusTier: tier },
  items: { data: [{ id: "si_1", price: { id: `price_${tier}`, lookup_key: `cyrus_plan_${tier}_v1`, metadata: {} }, current_period_start: Math.floor((end - 30 * DAY) / 1000), current_period_end: Math.floor(end / 1000) }] },
});
const inv = (id: string, subId: string, userId: string, tier: string, reason: string, paid: number, pi: string) => ({
  id, status: "paid", billing_reason: reason, amount_paid: paid, livemode: false,
  parent: { subscription_details: { subscription: subId, metadata: { cyrusUserId: userId } } },
  payments: { data: [{ payment: { payment_intent: pi } }] },
  lines: { data: [{ amount: paid, period: { end: Math.floor((Date.now() + 30 * DAY) / 1000) }, pricing: { price_details: { price: `price_${tier}` } } }] },
});
const ev = (type: string, object: unknown) => ({ id: `evt_${uniq()}`, type, data: { object } }) as unknown as import("stripe").Stripe.Event;

describe("stripe: plan invoices, replays, stacking, upgrade, refund", { skip }, () => {
  it("first invoice grants the plan's tokens once, however often the webhook is replayed", async () => {
    const u = await mkUser();
    const state = { subs: { sub_a: sub("sub_a", u.id, "katara") }, invoices: [inv("in_1", "sub_a", u.id, "katara", "subscription_create", 499, "pi_1")], sessions: {} };
    S.setCyrusStripeForTests(fakeStripe(state) as never);
    for (let i = 0; i < 3; i++) await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[0]));
    await S.handleCyrusStripeEvent(ev("customer.subscription.updated", state.subs.sub_a));
    assert.equal(await bal(u.id), 750);
    const plan = await db.cyrusPlan.findUnique({ where: { userId: u.id } });
    assert.equal(plan?.tier, "katara"); assert.equal(plan?.status, "active");
    // A renewal stacks.
    state.invoices.push(inv("in_2", "sub_a", u.id, "katara", "subscription_cycle", 499, "pi_2"));
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[1]));
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[1]));
    assert.equal(await bal(u.id), 1500);
    // Upgrade proration: tokens in proportion to the money, entitlement moves up.
    state.subs.sub_a = sub("sub_a", u.id, "all");
    state.invoices.push(inv("in_3", "sub_a", u.id, "all", "subscription_update", 2250, "pi_3"));
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[2]));
    assert.equal(await bal(u.id), 1500 + 4501);
    assert.equal((await db.cyrusPlan.findUnique({ where: { userId: u.id } }))?.tier, "all");
    // Refund half of the renewal payment: half of that invoice's tokens come back off (unspent).
    await S.handleCyrusStripeEvent(ev("charge.refunded", { id: "ch_2", payment_intent: "pi_2", amount: 499, amount_refunded: 250 }));
    await S.handleCyrusStripeEvent(ev("charge.refunded", { id: "ch_2", payment_intent: "pi_2", amount: 499, amount_refunded: 250 }));
    assert.equal(await bal(u.id), 1500 + 4501 - 376);
    // Then the rest of it.
    await S.handleCyrusStripeEvent(ev("charge.refunded", { id: "ch_2", payment_intent: "pi_2", amount: 499, amount_refunded: 499 }));
    assert.equal(await bal(u.id), 1500 + 4501 - 750);
  });
  it("rollover: plan tokens stack to 3 months; the 4th renewal expires the oldest", async () => {
    const u = await mkUser();
    const state = { subs: { sub_r: sub("sub_r", u.id, "katara") }, invoices: [] as Inv[], sessions: {} };
    S.setCyrusStripeForTests(fakeStripe(state) as never);
    for (let i = 0; i < 4; i++) {
      state.invoices.push(inv(`in_r${i}_${uniq()}`, "sub_r", u.id, "katara", i ? "subscription_cycle" : "subscription_create", 499, `pi_r${i}`));
      await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[i]));
    }
    assert.equal(await bal(u.id), 2250);
  });
  it("cancel: the paid month keeps its unlock; after the period the plan's tokens get the grace expiry", async () => {
    const u = await mkUser();
    const end = Date.now() + 10 * DAY;
    const state = { subs: { sub_c: sub("sub_c", u.id, "saka", "active", end) }, invoices: [inv("in_c1", "sub_c", u.id, "saka", "subscription_create", 1999, "pi_c1")], sessions: {} };
    S.setCyrusStripeForTests(fakeStripe(state) as never);
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[0]));
    state.subs.sub_c = { ...sub("sub_c", u.id, "saka", "canceled", end), ended_at: Math.floor(Date.now() / 1000) };
    await S.handleCyrusStripeEvent(ev("customer.subscription.deleted", state.subs.sub_c));
    const { tierOf } = await import("../lib/cyrus/tokens/access.ts");
    assert.equal(await tierOf(u.id), "saka");
    const lot = await db.cyrusTokenLot.findFirst({ where: { userId: u.id, source: "plan" } });
    assert.ok(lot?.expiresAt && Math.abs(lot.expiresAt.getTime() - (end + 30 * DAY)) < 5000);
  });
  it("top-up session: replayed checkout events and the return leg grant once; amount paid is the truth", async () => {
    const u = await mkUser();
    const session = { id: `cs_test_${uniq()}`, mode: "payment", payment_status: "paid", amount_total: 1000, livemode: false, payment_intent: "pi_t1", metadata: { cyrusUserId: u.id, cyrusKind: "topup", cyrusTokens: "99999", cyrusCents: "1000" } };
    const state = { subs: {}, invoices: [], sessions: { [session.id]: session } };
    S.setCyrusStripeForTests(fakeStripe(state) as never);
    await S.handleCyrusStripeEvent(ev("checkout.session.completed", session));
    await S.handleCyrusStripeEvent(ev("checkout.session.completed", session));
    await S.fulfilCyrusSession(session.id);
    assert.equal(await bal(u.id), 1200);
  });
  it("events that aren't Cyrus are ignored", async () => {
    S.setCyrusStripeForTests(fakeStripe({ subs: {}, invoices: [], sessions: {} }) as never);
    assert.equal(await S.handleCyrusStripeEvent(ev("checkout.session.completed", { id: "cs_x", metadata: { nxeonUserId: "u" } })), false);
    assert.equal(await S.handleCyrusStripeEvent(ev("invoice.paid", { id: "in_x", parent: null })), false);
  });
});

