import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * DB-backed checks of the Cyrus token ledger, grants and Stripe webhook handling against a
 * THROWAWAY Postgres (no Stripe network: a fake client is injected).
 *
 * Opt-in and fail-closed: runs only when CYRUS_TOKENS_TEST_DATABASE_URL is set, equals
 * DATABASE_URL, points at localhost and the database name ends in `_cyrustokens` (the
 * agent DB `nxeon_agt_cyrustokens`, schema pushed with `npx prisma db push`).
 *
 *   DATABASE_URL=postgresql://...@localhost:5432/nxeon_agt_cyrustokens \
 *   CYRUS_TOKENS_TEST_DATABASE_URL=$DATABASE_URL npx tsx --test test/cyrus-tokens-ledger-db.test.ts
 */
const url = process.env.CYRUS_TOKENS_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@(localhost|127\.0\.0\.1)(:\d+)?\/[a-z_]*_cyrustokens$/.test(url);
const skip = safe ? false : "set CYRUS_TOKENS_TEST_DATABASE_URL (= DATABASE_URL, a throwaway *_cyrustokens db) to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let L: typeof import("../lib/cyrus/tokens/ledger.ts");
let G: typeof import("../lib/cyrus/tokens/grants.ts");
let B: typeof import("../lib/cyrus/tokens/builds.ts");
let S: typeof import("../lib/cyrus/tokens/billing.ts");
let C: typeof import("../lib/cyrus/tokens/config.ts");
const DAY = 86_400_000;
const uniq = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
const users: string[] = [];

async function mkUser(opts: { email?: string; createdAt?: Date } = {}) {
  const u = await db.user.create({ data: { email: opts.email ?? `cyt-${uniq()}@example.test`, passwordHash: "x", name: "Cyrus Token Test", ...(opts.createdAt ? { createdAt: opts.createdAt } : {}) } });
  users.push(u.id);
  return u;
}
const bal = async (userId: string) => (await L.tokenSummary(userId)).balance;

before(async () => {
  if (!safe) return;
  db = (await import("../lib/db.ts")).db;
  L = await import("../lib/cyrus/tokens/ledger.ts");
  G = await import("../lib/cyrus/tokens/grants.ts");
  B = await import("../lib/cyrus/tokens/builds.ts");
  S = await import("../lib/cyrus/tokens/billing.ts");
  C = await import("../lib/cyrus/tokens/config.ts");
  await db.setting.upsert({ where: { key: "cyrus_tok_live" }, update: { value: "true" }, create: { key: "cyrus_tok_live", value: "true" } });
  C.clearTokenConfigCache();
});

after(async () => {
  if (!safe) return;
  await db.setting.deleteMany({ where: { key: { startsWith: "cyrus_tok_" } } });
  for (const t of ["cyrusTokenLedger", "cyrusTokenLot", "cyrusTokenReservation", "cyrusTokenAccount", "cyrusPlan"] as const) {
    await (db[t] as unknown as { deleteMany: (a: unknown) => Promise<unknown> }).deleteMany({ where: { userId: { in: users } } });
  }
  await db.modBuild.deleteMany({ where: { userId: { in: users } } });
  await db.user.deleteMany({ where: { id: { in: users } } });
  S.setCyrusStripeForTests(null);
  await db.$disconnect();
});

describe("ledger: idempotent credits", { skip }, () => {
  it("the same idemKey credits once, even when fired concurrently", async () => {
    const u = await mkUser();
    const key = `t:${uniq()}`;
    const rs = await Promise.all(Array.from({ length: 6 }, () => L.creditTokens({ userId: u.id, amount: 250, kind: "grant", source: "admin", idemKey: key })));
    assert.equal(rs.filter((r) => r.created).length, 1);
    assert.equal(await bal(u.id), 250);
    assert.equal(await db.cyrusTokenLot.count({ where: { userId: u.id } }), 1);
    assert.equal(await db.cyrusTokenLedger.count({ where: { idemKey: key } }), 1);
  });
  it("a capped (zero) credit is still final", async () => {
    const u = await mkUser();
    const key = `t:${uniq()}`;
    const r1 = await L.creditTokens({ userId: u.id, amount: 100, kind: "grant", source: "admin", idemKey: key, clamp: async () => ({ amount: 0, note: "capped" }) });
    const r2 = await L.creditTokens({ userId: u.id, amount: 100, kind: "grant", source: "admin", idemKey: key });
    assert.equal(r1.amount, 0);
    assert.equal(r2.created, false);
    assert.equal(await bal(u.id), 0);
  });
});

describe("ledger: reserve -> settle / release", { skip }, () => {
  it("holds the high end, spends the actual cost, releases the rest; settling twice is a no-op", async () => {
    const u = await mkUser();
    await L.creditTokens({ userId: u.id, amount: 250, kind: "grant", source: "admin", idemKey: `t:${uniq()}` });
    const buildId = `cyt${uniq()}`;
    const r = await L.reserveTokens({ userId: u.id, buildId, model: "katara", need: 30, pick: (a) => (a >= 140 ? 140 : null), dailyCap: () => 5000 });
    assert.deepEqual(r.ok && r.amount, 140);
    const again = await L.reserveTokens({ userId: u.id, buildId, model: "katara", need: 30, pick: () => 140, dailyCap: () => 5000 });
    assert.ok(again.ok && !again.created, "reserve is idempotent per build");
    let s = await L.tokenSummary(u.id);
    assert.equal(s.balance, 250); assert.equal(s.reserved, 140); assert.equal(s.available, 110);
    const st = await L.settleReservation({ buildId, charge: 80, reason: "succeeded", costUsd: 0.1587 });
    assert.equal(st?.charged, 80); assert.equal(st?.released, 60);
    const st2 = await L.settleReservation({ buildId, charge: 80, reason: "succeeded" });
    assert.equal(st2?.settled, false);
    s = await L.tokenSummary(u.id);
    assert.equal(s.balance, 170); assert.equal(s.reserved, 0);
    assert.equal(await db.cyrusTokenLedger.count({ where: { buildId, kind: "spend" } }), 1);
  });
  it("a failed build releases everything", async () => {
    const u = await mkUser();
    await L.creditTokens({ userId: u.id, amount: 100, kind: "grant", source: "admin", idemKey: `t:${uniq()}` });
    const buildId = `cyt${uniq()}`;
    await L.reserveTokens({ userId: u.id, buildId, model: "saka", need: 35, pick: () => 100, dailyCap: () => 5000 });
    await L.settleReservation({ buildId, charge: 0, reason: "failed_free" });
    const s = await L.tokenSummary(u.id);
    assert.equal(s.balance, 100); assert.equal(s.reserved, 0);
    assert.equal((await db.cyrusTokenReservation.findUnique({ where: { buildId } }))?.status, "released");
  });
  it("an overrun never goes negative: the excess is written off", async () => {
    const u = await mkUser();
    await L.creditTokens({ userId: u.id, amount: 50, kind: "grant", source: "admin", idemKey: `t:${uniq()}` });
    const buildId = `cyt${uniq()}`;
    await L.reserveTokens({ userId: u.id, buildId, model: "katara", need: 30, pick: (a) => a, dailyCap: () => 5000 });
    const st = await L.settleReservation({ buildId, charge: 220, reason: "succeeded" });
    assert.equal(st?.charged, 50); assert.equal(st?.writeoff, 170);
    assert.equal(await bal(u.id), 0);
  });
  it("too few tokens and the daily cap both refuse", async () => {
    const u = await mkUser();
    await L.creditTokens({ userId: u.id, amount: 20, kind: "grant", source: "admin", idemKey: `t:${uniq()}` });
    const r = await L.reserveTokens({ userId: u.id, buildId: `cyt${uniq()}`, model: "katara", need: 30, pick: (a) => (a >= 30 ? a : null), dailyCap: () => 5000 });
    assert.equal(!r.ok && r.code, "insufficient_tokens");
    await L.creditTokens({ userId: u.id, amount: 1000, kind: "grant", source: "admin", idemKey: `t:${uniq()}` });
    const r1 = await L.reserveTokens({ userId: u.id, buildId: `cyt${uniq()}`, model: "katara", need: 30, pick: () => 300, dailyCap: () => 500 });
    assert.ok(r1.ok);
    const r2 = await L.reserveTokens({ userId: u.id, buildId: `cyt${uniq()}`, model: "katara", need: 30, pick: () => 300, dailyCap: () => 500 });
    assert.equal(!r2.ok && r2.code, "daily_cap");
  });
  it("two builds racing for the last tokens: only one gets them", async () => {
    const u = await mkUser();
    await L.creditTokens({ userId: u.id, amount: 100, kind: "grant", source: "admin", idemKey: `t:${uniq()}` });
    const rs = await Promise.all([1, 2].map(() => L.reserveTokens({ userId: u.id, buildId: `cyt${uniq()}`, model: "katara", need: 70, pick: (a) => (a >= 70 ? 70 : null), dailyCap: () => 5000 })));
    assert.equal(rs.filter((r) => r.ok).length, 1);
  });
});

describe("ledger: expiry, FIFO, revoke", { skip }, () => {
  it("spends the soonest-expiring lot first and expires due lots before spending", async () => {
    const u = await mkUser();
    const now = new Date();
    await L.creditTokens({ userId: u.id, amount: 100, kind: "grant", source: "admin", idemKey: `t:${uniq()}`, expiresAt: new Date(now.getTime() + 300 * DAY) });
    const soon = await L.creditTokens({ userId: u.id, amount: 60, kind: "grant", source: "server_initial", idemKey: `t:${uniq()}`, expiresAt: new Date(now.getTime() + 10 * DAY) });
    await L.creditTokens({ userId: u.id, amount: 40, kind: "grant", source: "admin", idemKey: `t:${uniq()}`, expiresAt: new Date(now.getTime() + 1 * DAY) });
    const later = new Date(now.getTime() + 2 * DAY); // the 40-token lot is now past due
    const buildId = `cyt${uniq()}`;
    await L.reserveTokens({ userId: u.id, buildId, model: "katara", need: 10, pick: () => 70, dailyCap: () => 5000, now: later });
    await L.settleReservation({ buildId, charge: 70, reason: "succeeded", now: later });
    const lot = await db.cyrusTokenLot.findUnique({ where: { id: soon.lotId! } });
    assert.equal(lot?.remaining, 0, "the 10-day lot went first");
    assert.equal(await db.cyrusTokenLedger.count({ where: { userId: u.id, kind: "expire" } }), 1);
    assert.equal(await bal(u.id), 90);
  });
  it("revoke never takes tokens a running build holds", async () => {
    const u = await mkUser();
    await L.creditTokens({ userId: u.id, amount: 100, kind: "grant", source: "admin", idemKey: `t:${uniq()}` });
    await L.reserveTokens({ userId: u.id, buildId: `cyt${uniq()}`, model: "katara", need: 10, pick: () => 70, dailyCap: () => 5000 });
    const r = await L.revokeTokens({ userId: u.id, amount: 100, idemKey: `t:${uniq()}`, note: "test" });
    assert.equal(r.revoked, 30);
    assert.equal(await bal(u.id), 70);
  });
});

describe("game-server grants", { skip }, () => {
  it("purchase grants once per server; renewal grants once per period; renewals are smaller", async () => {
    const u = await mkUser();
    const serverId = `srv${uniq()}`;
    const a = await G.grantForGameServerPurchase({ userId: u.id, serverId, gameFamily: "minecraft", chargeCents: 899, termMonths: 1 });
    const b = await G.grantForGameServerPurchase({ userId: u.id, serverId, gameFamily: "minecraft", chargeCents: 899, termMonths: 1 });
    assert.equal(a?.amount, 245); assert.equal(b?.created, false);
    const p1 = new Date("2026-11-07T00:00:00Z");
    const r1 = await G.grantForGameServerRenewal({ userId: u.id, serverId, netCents: 899, months: 1, periodStart: p1 });
    const r1b = await G.grantForGameServerRenewal({ userId: u.id, serverId, netCents: 899, months: 1, periodStart: p1 });
    const r2 = await G.grantForGameServerRenewal({ userId: u.id, serverId, netCents: 899, months: 1, periodStart: new Date("2026-12-07T00:00:00Z") });
    assert.equal(r1?.amount, 80); assert.equal(r1b?.created, false); assert.equal(r2?.amount, 80);
    assert.equal(await bal(u.id), 245 + 80 + 80);
  });
  it("a $0 (trial) start gets its initial grant on the first paid renewal instead", async () => {
    const u = await mkUser();
    const serverId = `srv${uniq()}`;
    assert.equal(await G.grantForGameServerPurchase({ userId: u.id, serverId, chargeCents: 0, termMonths: 1 }), null);
    const r = await G.grantForGameServerRenewal({ userId: u.id, serverId, netCents: 1599, months: 1, periodStart: new Date() });
    assert.equal(r?.amount, 355);
    assert.equal((await db.cyrusTokenLedger.findUnique({ where: { idemKey: G.initialKey(serverId) } }))?.delta, 355);
  });
  it("farming: only 3 initial grants per 30 days per account", async () => {
    const u = await mkUser();
    const out = [];
    for (let i = 0; i < 5; i++) out.push(await G.grantForGameServerPurchase({ userId: u.id, serverId: `srv${uniq()}`, chargeCents: 299, termMonths: 1 }));
    assert.deepEqual(out.map((r) => r?.amount), [150, 150, 150, 0, 0]);
  });
  it("not launched: only preview accounts earn", async () => {
    await db.setting.update({ where: { key: "cyrus_tok_live" }, data: { value: "false" } });
    C.clearTokenConfigCache();
    try {
      const u = await mkUser();
      assert.equal(await G.grantForGameServerPurchase({ userId: u.id, serverId: `srv${uniq()}`, chargeCents: 899, termMonths: 1 }), null);
    } finally {
      await db.setting.update({ where: { key: "cyrus_tok_live" }, data: { value: "true" } });
      C.clearTokenConfigCache();
    }
  });
});

describe("builds: gate + settle", { skip }, () => {
  it("free accounts are Katara-only; a build reserves, then settles to the actual cost", async () => {
    const u = await mkUser();
    await L.creditTokens({ userId: u.id, amount: 250, kind: "grant", source: "server_initial", idemKey: `t:${uniq()}` });
    const locked = await B.gateBuild({ user: u, buildId: `mb${uniq()}`, requested: "yakko", baseModel: undefined, text: "a /heal command" });
    assert.equal(!locked.ok && locked.code, "model_locked");
    const id = `mb${uniq()}`;
    const g = await B.gateBuild({ user: u, buildId: id, requested: undefined, baseModel: undefined, text: "A /heal command that heals the player" });
    assert.ok(g.ok && g.model === "katara" && g.reserved === 70);
    const row = await db.modBuild.create({ data: { id, userId: u.id, prompt: "x", mcVersion: "1.21.11", status: "succeeded", costUsd: 0.1587, cyrus: { model: "katara" } } });
    await B.settleBuildTokens(row);
    await B.settleBuildTokens(row);
    assert.equal(await bal(u.id), 170);
  });
  it("our-side failures are free up to the daily allowance", async () => {
    const u = await mkUser();
    await L.creditTokens({ userId: u.id, amount: 1000, kind: "grant", source: "admin", idemKey: `t:${uniq()}` });
    const id = `mb${uniq()}`;
    await B.gateBuild({ user: u, buildId: id, requested: "katara", baseModel: undefined, text: "a /heal command" });
    const row = await db.modBuild.create({ data: { id, userId: u.id, prompt: "x", mcVersion: "1.21.11", status: "failed", errorCode: "compile", costUsd: 0.3, cyrus: { model: "katara" } } });
    await B.settleBuildTokens(row);
    assert.equal(await bal(u.id), 1000);
  });
});

// ---------------------------------------------------------------------------
// Stripe webhooks with a fake client (replays, stacking, upgrade, refund)
// ---------------------------------------------------------------------------

type Inv = Record<string, unknown>;
function fakeStripe(state: { subs: Record<string, Record<string, unknown>>; invoices: Inv[]; sessions: Record<string, Record<string, unknown>> }) {
  const price = (tier: string) => ({ id: `price_${tier}`, lookup_key: `cyrus_plan_${tier}_v1`, unit_amount: { katara: 499, saka: 1999, all: 4999 }[tier], currency: "usd", livemode: false, metadata: {} });
  return {
    prices: {
      list: async () => ({ data: ["katara", "saka", "all"].map(price) }),
      retrieve: async (id: string) => price(id.replace("price_", "")),
    },
    subscriptions: { retrieve: async (id: string) => state.subs[id], update: async () => ({}) },
    invoices: { list: async (q: { subscription: string }) => ({ data: state.invoices.filter((i) => (i.parent as { subscription_details: { subscription: string } }).subscription_details.subscription === q.subscription).slice().reverse() }) },
    invoicePayments: { list: async () => ({ data: [] }) },
    checkout: { sessions: { retrieve: async (id: string) => state.sessions[id], create: async () => ({ client_secret: "cs_secret" }) } },
    customers: { create: async () => ({ id: `cus_${uniq()}` }) },
  };
}
const sub = (id: string, userId: string, tier: string, status = "active", end = Date.now() + 30 * DAY) => ({
  id, status, customer: "cus_x", livemode: false, cancel_at_period_end: false, ended_at: null,
  metadata: { cyrusUserId: userId, cyrusTier: tier },
  items: { data: [{ id: "si_1", price: { id: `price_${tier}`, lookup_key: `cyrus_plan_${tier}_v1`, metadata: {} }, current_period_start: Math.floor((end - 30 * DAY) / 1000), current_period_end: Math.floor(end / 1000) }] },
});
const inv = (id: string, subId: string, userId: string, tier: string, reason: string, paid: number, pi: string) => ({
  id, status: "paid", billing_reason: reason, amount_paid: paid, livemode: false,
  parent: { subscription_details: { subscription: subId, metadata: { cyrusUserId: userId } } },
  payments: { data: [{ payment: { payment_intent: pi } }] },
  lines: { data: [{ amount: paid, period: { end: Math.floor((Date.now() + 30 * DAY) / 1000) }, pricing: { price_details: { price: `price_${tier}` } } }] },
});
const ev = (type: string, object: unknown) => ({ id: `evt_${uniq()}`, type, data: { object } }) as unknown as import("stripe").Stripe.Event;

describe("stripe: plan invoices, replays, stacking, upgrade, refund", { skip }, () => {
  it("first invoice grants the plan's tokens once, however often the webhook is replayed", async () => {
    const u = await mkUser();
    const state = { subs: { sub_a: sub("sub_a", u.id, "katara") }, invoices: [inv("in_1", "sub_a", u.id, "katara", "subscription_create", 499, "pi_1")], sessions: {} };
    S.setCyrusStripeForTests(fakeStripe(state) as never);
    for (let i = 0; i < 3; i++) await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[0]));
    await S.handleCyrusStripeEvent(ev("customer.subscription.updated", state.subs.sub_a));
    assert.equal(await bal(u.id), 750);
    const plan = await db.cyrusPlan.findUnique({ where: { userId: u.id } });
    assert.equal(plan?.tier, "katara"); assert.equal(plan?.status, "active");
    // A renewal stacks.
    state.invoices.push(inv("in_2", "sub_a", u.id, "katara", "subscription_cycle", 499, "pi_2"));
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[1]));
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[1]));
    assert.equal(await bal(u.id), 1500);
    // Upgrade proration: tokens in proportion to the money, entitlement moves up.
    state.subs.sub_a = sub("sub_a", u.id, "all");
    state.invoices.push(inv("in_3", "sub_a", u.id, "all", "subscription_update", 2250, "pi_3"));
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[2]));
    assert.equal(await bal(u.id), 1500 + 4501);
    assert.equal((await db.cyrusPlan.findUnique({ where: { userId: u.id } }))?.tier, "all");
    // Refund half of the renewal payment: half of that invoice's tokens come back off (unspent).
    await S.handleCyrusStripeEvent(ev("charge.refunded", { id: "ch_2", payment_intent: "pi_2", amount: 499, amount_refunded: 250 }));
    await S.handleCyrusStripeEvent(ev("charge.refunded", { id: "ch_2", payment_intent: "pi_2", amount: 499, amount_refunded: 250 }));
    assert.equal(await bal(u.id), 1500 + 4501 - 376);
    // Then the rest of it.
    await S.handleCyrusStripeEvent(ev("charge.refunded", { id: "ch_2", payment_intent: "pi_2", amount: 499, amount_refunded: 499 }));
    assert.equal(await bal(u.id), 1500 + 4501 - 750);
  });
  it("rollover: plan tokens stack to 3 months; the 4th renewal expires the oldest", async () => {
    const u = await mkUser();
    const state = { subs: { sub_r: sub("sub_r", u.id, "katara") }, invoices: [] as Inv[], sessions: {} };
    S.setCyrusStripeForTests(fakeStripe(state) as never);
    for (let i = 0; i < 4; i++) {
      state.invoices.push(inv(`in_r${i}_${uniq()}`, "sub_r", u.id, "katara", i ? "subscription_cycle" : "subscription_create", 499, `pi_r${i}`));
      await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[i]));
    }
    assert.equal(await bal(u.id), 2250);
  });
  it("cancel: the paid month keeps its unlock; after the period the plan's tokens get the grace expiry", async () => {
    const u = await mkUser();
    const end = Date.now() + 10 * DAY;
    const state = { subs: { sub_c: sub("sub_c", u.id, "saka", "active", end) }, invoices: [inv("in_c1", "sub_c", u.id, "saka", "subscription_create", 1999, "pi_c1")], sessions: {} };
    S.setCyrusStripeForTests(fakeStripe(state) as never);
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[0]));
    state.subs.sub_c = { ...sub("sub_c", u.id, "saka", "canceled", end), ended_at: Math.floor(Date.now() / 1000) };
    await S.handleCyrusStripeEvent(ev("customer.subscription.deleted", state.subs.sub_c));
    const { tierOf } = await import("../lib/cyrus/tokens/access.ts");
    assert.equal(await tierOf(u.id), "saka");
    const lot = await db.cyrusTokenLot.findFirst({ where: { userId: u.id, source: "plan" } });
    assert.ok(lot?.expiresAt && Math.abs(lot.expiresAt.getTime() - (end + 30 * DAY)) < 5000);
  });
  it("top-up session: replayed checkout events and the return leg grant once; amount paid is the truth", async () => {
    const u = await mkUser();
    const session = { id: `cs_test_${uniq()}`, mode: "payment", payment_status: "paid", amount_total: 1000, livemode: false, payment_intent: "pi_t1", metadata: { cyrusUserId: u.id, cyrusKind: "topup", cyrusTokens: "99999", cyrusCents: "1000" } };
    const state = { subs: {}, invoices: [], sessions: { [session.id]: session } };
    S.setCyrusStripeForTests(fakeStripe(state) as never);
    await S.handleCyrusStripeEvent(ev("checkout.session.completed", session));
    await S.handleCyrusStripeEvent(ev("checkout.session.completed", session));
    await S.fulfilCyrusSession(session.id);
    assert.equal(await bal(u.id), 1200);
  });
  it("events that aren't Cyrus are ignored", async () => {
    S.setCyrusStripeForTests(fakeStripe({ subs: {}, invoices: [], sessions: {} }) as never);
    assert.equal(await S.handleCyrusStripeEvent(ev("checkout.session.completed", { id: "cs_x", metadata: { nxeonUserId: "u" } })), false);
    assert.equal(await S.handleCyrusStripeEvent(ev("invoice.paid", { id: "in_x", parent: null })), false);
  });
});

