"use client";

import { useId } from "react";
import { cyrusTokens, fmtTokens, useCyrusTokens } from "./store";

/** The Cyrus token mark: a faceted hex coin in the studio's cyan-violet-magenta. */
export function TokenGlyph({ size = 14, className = "" }: { size?: number; className?: string }) {
  const id = useId().replace(/:/g, "");
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" className={className} aria-hidden="true">
      <defs>
        <linearGradient id={`cyt-g${id}`} x1="3" y1="3" x2="21" y2="21" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#14c5e4" /><stop offset=".55" stopColor="#8c3ae9" /><stop offset="1" stopColor="#d623e1" />
        </linearGradient>
      </defs>
      <path d="M12 2.5 20.2 7.25v9.5L12 21.5 3.8 16.75v-9.5z" fill={`url(#cyt-g${id})`} opacity=".22" />
      <path d="M12 2.5 20.2 7.25v9.5L12 21.5 3.8 16.75v-9.5z" fill="none" stroke={`url(#cyt-g${id})`} strokeWidth="1.6" strokeLinejoin="round" />
      <path d="M12 7.2 15.9 9.5v4.9L12 16.8l-3.9-2.4V9.5z" fill={`url(#cyt-g${id})`} />
    </svg>
  );
}

/** "Beta · Minecraft Java only" — Cyrus's launch scope, said once wherever tokens are. */
export function BetaLabel({ short = false }: { short?: boolean }) {
  return <span className="cyt-beta" title="Cyrus is in beta and builds Minecraft Java server plugins only">Beta{short ? "" : " · Minecraft Java only"}</span>;
}

/** Balance chip + "Get tokens". Renders nothing for accounts outside the token economy. */
export function CyrusTokenChip({ compact = false, beta = true }: { compact?: boolean; beta?: boolean }) {
  const { state } = useCyrusTokens();
  if (!state?.active) return null;
  const low = state.available < state.lowBalance;
  return (
    <span className={`cyt-chipwrap ${compact ? "compact" : ""}`}>
      {beta && !compact && <BetaLabel />}
      <button type="button" className={`cyt-chip ${low ? "low" : ""}`} onClick={() => cyrusTokens.open({ tab: "plans" })}
              title={`${fmtTokens(state.available)} tokens available${state.reserved ? ` (${fmtTokens(state.reserved)} held by a running build)` : ""}`}
              aria-label={`${fmtTokens(state.available)} Cyrus tokens. Get tokens`}>
        <TokenGlyph size={15} />
        <b>{fmtTokens(state.available)}</b>
        {!compact && <span className="cyt-chip-u">tokens</span>}
        <span className="cyt-chip-get">{low ? "Get tokens" : compact ? "+" : "Get tokens"}</span>
      </button>
    </span>
  );
}

