"use client";

import { estimate } from "@/lib/cyrus/estimate";
import type { CyrusModelId } from "@/lib/cyrus/models";
import { cyrusTokens, fmtTokens, useCyrusTokens } from "./store";
import { TokenGlyph } from "./TokenChip";

/**
 * Composer estimate in TOKENS (replaces the old USD figure): time range + the token range
 * this build will most likely spend (the high end is what it holds while it runs).
 * Accounts outside the token economy see the time only.
 */
export function CyrusTokenEstimate({ text, model, change }: { text: string; model: CyrusModelId; change?: boolean }) {
  const { state } = useCyrusTokens();
  if (!text.trim()) return null;
  const e = estimate(text, model, { change });
  const range = state?.active ? state.reserve[model]?.[e.complexity] : null;
  const locked = !!state?.active && state.enforce && !state.models.includes(model);
  const short = !!range && state!.enforce && state!.available < range[0];
  return (
    <span className={`cy-est cyt-est ${short || locked ? "warn" : ""}`} title={range ? `Estimated from real builds. A build holds up to ${fmtTokens(range[1])} tokens while it runs and only spends what it actually uses. Failed builds give the tokens back.` : "Estimate"}>
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true"><circle cx="12" cy="12" r="8" /><path d="M12 8v4.5l3 1.8" /></svg>
      ~{e.minutes[0]}–{e.minutes[1]} min
      {range && (
        <>
          <span className="cy-est-sep">·</span>
          <TokenGlyph size={12} /> ≈ {fmtTokens(range[0])}–{fmtTokens(range[1])}
          {(short || locked) && (
            <button type="button" className="cyt-est-get" onClick={() => cyrusTokens.open({ reason: locked ? "model_locked" : "insufficient_tokens" })}>
              {locked ? "Unlock" : "Get tokens"}
            </button>
          )}
        </>
      )}
    </span>
  );
}
