"use client";

import type { CyrusModelId } from "@/lib/cyrus/models";
import { TIER_LABEL, tierForModel } from "@/lib/cyrus/tokens/economy";
import { cyrusTokens, useCyrusTokens } from "./store";

/** "Saka plan" lock pill on a model the account hasn't unlocked (nothing when unlocked or outside the economy). */
export function CyrusModelLock({ model }: { model: CyrusModelId }) {
  const { state } = useCyrusTokens();
  if (!state?.active || !state.enforce || state.models.includes(model)) return null;
  return (
    <span className="cyt-lock" title={`Unlocks with the ${TIER_LABEL[tierForModel(model)]} plan`}>
      <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" aria-hidden="true"><path d="M6 10.5h12V20H6z M8.5 10.5V7.8a3.5 3.5 0 0 1 7 0v2.7" /></svg>
      {TIER_LABEL[tierForModel(model)]}
    </span>
  );
}

/** Model-picker footer: replaces "Nothing is charged during the preview". */
export function CyrusModelPanelFoot({ fallback }: { fallback?: string }) {
  const { state } = useCyrusTokens();
  if (!state?.active) return fallback ? <p className="cy-panel-foot">{fallback}</p> : null;
  const locked = state.enforce && state.models.length < 3;
  return (
    <p className="cy-panel-foot cyt-foot">
      Builds spend tokens for what they actually use; a failed build gives them back.
      {locked && <> <button type="button" onMouseDown={(e) => e.preventDefault()} onClick={() => cyrusTokens.open({ tab: "plans", reason: "model_locked" })}>Unlock more models</button></>}
    </p>
  );
}
