        {pay ? (
          <PayStep pay={pay} onBack={() => setPay(null)} />
        ) : (
          <>
            <div className="cyt-tabs" role="tablist">
              {(["plans", "topup", "history"] as TokensTab[]).map((t) => (
                <button key={t} type="button" role="tab" aria-selected={tab === t} className={`cy-seg ${tab === t ? "on" : ""}`} onClick={() => cyrusTokens.setTab(t)}>
                  {t === "plans" ? "Plans" : t === "topup" ? "Top up" : "History"}
                </button>
              ))}
            </div>
            {err && <p className="cyt-err" role="alert">{err}</p>}
            {msg && <p className="cyt-ok" role="status">{msg}</p>}
            {tab === "plans" && <Plans state={state} busy={busy} onBuy={(p) => checkout({ kind: "plan", tier: p.tier }, `${p.name} plan`)} onAction={planAction} />}
            {tab === "topup" && <Topup state={state} busy={busy} onPay={(cents) => checkout({ kind: "topup", cents }, `${fmtMoney(cents)} top-up`)} />}
            {tab === "history" && <History />}
          </>
        )}
      </div>
    </div>
  );
}

function Plans({ state, busy, onBuy, onAction }: { state: TokenState; busy: string | null; onBuy: (p: TokenPlanOffer) => void; onAction: (b: Record<string, unknown>, key: string) => void }) {
  const cur = state.plan?.active ? state.plan : null;
  const [confirm, setConfirm] = useState<PlanTier | null>(null);
  return (
    <div className="cyt-plans">
      <div className="cyt-plan-grid">
        {state.plans.map((p) => {
          const isCur = cur?.priceTier === p.tier;
          const up = cur ? RANK[p.tier] > RANK[cur.tier] : true;
          return (
            <div key={p.tier} className={`cyt-plan ${isCur ? "cur" : ""} t-${p.tier}`}>
              <div className="cyt-plan-h"><b>{p.name}</b>{isCur && <span className="cy-tag cur">Your plan</span>}{!cur && p.tier === "saka" && <span className="cy-tag">Popular</span>}</div>
              <div className="cyt-plan-p"><b>{fmtMoney(p.priceCents)}</b><span>/month</span></div>
              <div className="cyt-plan-t"><TokenGlyph size={14} /> {fmtTokens(p.tokens)} tokens every month</div>
              <Models ids={p.models} />
              <div className="cyt-plan-a">
                {!p.purchasable ? <button type="button" className="cy-btn sm" disabled>Coming soon</button>
                  : !cur ? <button type="button" className={`cy-btn sm ${p.tier === "saka" ? "primary" : ""}`} disabled={!!busy} onClick={() => onBuy(p)}>{busy === `${p.name} plan` ? "Opening…" : `Get ${p.name}`}</button>
                  : isCur ? (cur.cancelAtPeriodEnd
                      ? <button type="button" className="cy-btn sm" disabled={!!busy} onClick={() => onAction({ action: "resume" }, "resume")}>{busy === "resume" ? "…" : "Keep my plan"}</button>
                      : <span className="cyt-plan-note">Renews {cur.currentPeriodEnd ? day(cur.currentPeriodEnd) : "monthly"}</span>)
                  : confirm === p.tier ? (
                      <span className="cyt-confirm">
                        <span>{up ? "Charge the difference for the rest of this month to your card now?" : "Switch at your next renewal? You keep your current models until then."}</span>
                        <button type="button" className="cy-btn sm primary" disabled={!!busy} onClick={() => { setConfirm(null); onAction({ action: "change", tier: p.tier }, p.tier); }}>{busy === p.tier ? "…" : up ? "Upgrade" : "Switch"}</button>
                        <button type="button" className="cy-btn sm ghost" onClick={() => setConfirm(null)}>Not now</button>
                      </span>
                    )
                  : <button type="button" className={`cy-btn sm ${up ? "primary" : ""}`} disabled={!!busy} onClick={() => setConfirm(p.tier)}>{up ? `Upgrade to ${p.name}` : `Switch to ${p.name}`}</button>}
              </div>
            </div>
          );
        })}
      </div>
      <p className="cyt-fine">
        Plans renew monthly and every renewal adds its tokens on top of what you have. Unused plan tokens roll over, up to {state.rolloverMonths} months&apos; worth.
        Every game server you buy includes tokens too, plus more with each renewal. Without a plan you can build with Katara.
        {cur && !cur.cancelAtPeriodEnd && <> <button type="button" className="cyt-link" disabled={!!busy} onClick={() => onAction({ action: "cancel" }, "cancel")}>{busy === "cancel" ? "Cancelling…" : "Cancel plan"}</button> (you keep it until the end of the month you paid for).</>}
      </p>
    </div>
  );
}

function Topup({ state, busy, onPay }: { state: TokenState; busy: string | null; onPay: (cents: number) => void }) {
  const presets = [500, 1000, 2500, 5000].filter((c) => c >= state.topup.minCents && c <= state.topup.maxCents);
  const [cents, setCents] = useState(presets[1] ?? state.topup.minCents);
  const [custom, setCustom] = useState("");
  const tokens = Math.floor((cents / 100) * state.topup.tokensPerUsd);
  const ok = cents >= state.topup.minCents && cents <= state.topup.maxCents;
  if (!state.topup.enabled) return <p className="cyt-fine">Top-ups aren&apos;t available right now.</p>;
  return (
    <div className="cyt-topup">
      <div className="cyt-amounts">
        {presets.map((c) => (
          <button key={c} type="button" className={`cyt-amt ${cents === c && !custom ? "on" : ""}`} onClick={() => { setCents(c); setCustom(""); }}>
            <b>{fmtMoney(c)}</b><span>{fmtTokens(Math.floor((c / 100) * state.topup.tokensPerUsd))} tokens</span>
          </button>
        ))}
        <label className={`cyt-amt custom ${custom ? "on" : ""}`}>
          <span className="cyt-amt-k">Custom</span>
          <span className="cyt-amt-in">$<input inputMode="decimal" value={custom} placeholder="15" aria-label="Custom amount in dollars"
            onChange={(e) => { const v = e.target.value.replace(/[^0-9.]/g, "").slice(0, 7); setCustom(v); setCents(Math.round(Number(v || 0) * 100)); }} /></span>
        </label>
      </div>
      <div className="cyt-topup-go">
        <span>{ok ? <><TokenGlyph size={14} /> {fmtTokens(tokens)} tokens</> : `Pick ${fmtMoney(state.topup.minCents)} to ${fmtMoney(state.topup.maxCents)}`}</span>
        <button type="button" className="cy-btn primary" disabled={!ok || !!busy || !state.payments} onClick={() => onPay(cents)}>{busy ? "Opening…" : `Pay ${fmtMoney(cents)}`}</button>
      </div>
      <p className="cyt-fine">One-off, no subscription. Top-up tokens last 12 months and work with every model your plan unlocks. Plans give more tokens per dollar.</p>
    </div>
  );
}

function History() {
  const [h, setH] = useState<TokenHistory | null>(null);
  const [loading, setLoading] = useState(false);
  async function load(before?: string) {
    setLoading(true);
    const r = await fetch(`/api/cyrus/tokens?history=1${before ? `&before=${encodeURIComponent(before)}` : ""}`, { cache: "no-store" }).catch(() => null);
    if (r?.ok) { const j = (await r.json()) as TokenHistory; setH((cur) => (before && cur ? { rows: [...cur.rows, ...j.rows], more: j.more } : j)); }
    setLoading(false);
  }
  useEffect(() => { void load(); }, []);
  const hue = useMemo(() => Object.fromEntries(CYRUS_MODELS.map((m) => [m.id, m])), []);
  if (!h) return <p className="cyt-fine">{loading ? "Loading…" : "Couldn't load your history."}</p>;
  if (!h.rows.length) return <p className="cyt-fine">No token activity yet.</p>;
  return (
    <div className="cyt-hist">
      <ul>
        {h.rows.map((r) => (
          <li key={r.id} className={r.delta > 0 ? "plus" : r.delta < 0 ? "minus" : "zero"}>
            <span className="cyt-h-d">{new Date(r.at).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</span>
            <span className="cyt-h-l">
              {r.label}
              {r.model && hue[r.model] && <span className="cyt-h-m"><i style={{ background: hue[r.model].hue }} />{hue[r.model].name}</span>}
              {r.buildId && <a className="cyt-h-b" href={`/dashboard/cyrus/${r.buildId}`}>open</a>}
              {r.kind === "spend" && r.hold ? <span className="cyt-h-x">held {fmtTokens(r.hold)}</span> : null}
            </span>
            <span className="cyt-h-n">{r.delta > 0 ? "+" : ""}{r.delta ? fmtTokens(r.delta) : r.kind === "reserve" ? "held" : "0"}</span>
          </li>
        ))}
      </ul>
      {h.more && <button type="button" className="cy-btn sm" disabled={loading} onClick={() => load(h.rows[h.rows.length - 1]?.at)}>{loading ? "Loading…" : "Older"}</button>}
    </div>
  );
}

function PayStep({ pay, onBack }: { pay: Pay; onBack: () => void }) {
  const stripePromise = useMemo(() => stripeFor(pay.publishableKey), [pay.publishableKey]);
  const themeKey = useStripeThemeKey();
  return (
    <div className="cyt-pay">
      <div className="cyt-pay-h"><button type="button" className="cyt-link" onClick={onBack}>← Back</button><b>{pay.label}</b></div>
      <CheckoutElementsProvider key={themeKey} stripe={stripePromise} options={{ clientSecret: pay.clientSecret, elementsOptions: { appearance: currentStripeAppearance(), fonts: STRIPE_FONTS } }}>
        <PayForm />
      </CheckoutElementsProvider>
    </div>
  );
}

function PayForm() {
  const s = useCheckoutElements();
  const co = s.type === "success" ? s.checkout : undefined;
  const [confirming, setConfirming] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const total = co ? (co as unknown as { total?: { total?: { amount?: string } } }).total?.total?.amount : null;
  async function go() {
    if (!co) return;
    setErr(null); setConfirming(true);
    try {
      const r = await co.confirm();
      if (r.type === "error") setErr(r.error.message ?? "That card didn't go through. Try another.");
      // Success: Stripe returns the browser to /api/cyrus/tokens/return, which adds the tokens.
    } catch { setErr("Something went wrong. Nothing was charged."); }
    setConfirming(false);
  }
  return (
    <div className="cyt-payform">
      <div className="cyt-card"><PaymentElement options={{ layout: "tabs", paymentMethodOrder: ["card"] }} /></div>
      {err && <p className="cyt-err" role="alert">{err}</p>}
      <button type="button" className="cy-btn primary cyt-pay-go" disabled={confirming || !co?.canConfirm} onClick={go}>{confirming ? "Paying…" : `Pay${total ? ` ${total}` : ""}`}</button>
      <p className="cyt-fine">Card details go straight to Stripe and never touch Nxeon&apos;s servers.</p>
    </div>
  );
}

