"use client";

import { useEffect, useState } from "react";
import { TokenGlyph } from "./TokenChip";

/**
 * Game-server checkout line: "Includes N Cyrus tokens (+M every renewal) · Beta, Minecraft Java".
 * The server decides who sees it (GET /api/cyrus/tokens/checkout-line answers 404 to
 * everyone outside the token economy, i.e. everyone but the private preview until launch),
 * so for normal customers this renders nothing at all.
 */
export function CyrusCheckoutLine({ monthlyCents, termMonths }: { monthlyCents: number | null | undefined; termMonths: number }) {
  const [line, setLine] = useState<{ initial: number; renewal: number } | null>(null);
  useEffect(() => {
    if (!monthlyCents || monthlyCents <= 0) { setLine(null); return; }
    const ctl = new AbortController();
    const t = setTimeout(() => {
      fetch(`/api/cyrus/tokens/checkout-line?monthlyCents=${Math.round(monthlyCents)}&termMonths=${termMonths}`, { signal: ctl.signal, cache: "no-store" })
        .then(async (r) => setLine(r.ok ? ((await r.json()).line ?? null) : null))
        .catch(() => undefined);
    }, 150);
    return () => { clearTimeout(t); ctl.abort(); };
  }, [monthlyCents, termMonths]);
  if (!line) return null;
  return (
    <div className="flex items-start gap-2.5 rounded-xl border border-violet-400/20 bg-violet-500/[0.06] px-3 py-2 text-[12px] leading-snug text-tx-body" data-cyrus-checkout-line>
      <TokenGlyph size={16} className="mt-px flex-none" />
      <span>
        Includes <b className="text-white">{line.initial.toLocaleString("en-US")} Cyrus tokens</b> (+{line.renewal.toLocaleString("en-US")} every renewal)
        <span className="text-tx-faint"> · Beta, Minecraft Java</span>
      </span>
    </div>
  );
}

