  useEffect(() => { /* modal handles Esc */ }, []);
  const list = CYRUS_TEMPLATES.filter((t) => cat === "All" || t.cat === cat);
  return (
    <Modal title="Templates" sub="Every one builds on plain Paper. Pick one, then make it yours in the prompt." onClose={onClose} wide>
      <div className="cy-cats" role="tablist">
        {CYRUS_TEMPLATE_CATS.map((c) => <button key={c} type="button" role="tab" aria-selected={cat === c} className={`cy-cat ${cat === c ? "on" : ""}`} onClick={() => setCat(c)}>{c}</button>)}
      </div>
      <div className="cy-tpls">
        {list.map((t) => {
          const e = estimate(t.prompt, t.model);
          const m = cyrusModel(t.model);
          return (
            <button key={t.id} type="button" className="cy-tpl" onClick={() => onUse(t)}>
              <span className="cy-tpl-top"><Glyph id={`tpl-${t.id}`} size={30} /><span className="cy-tpl-cat">{t.cat}</span></span>
              <b className="cy-tpl-t">{t.title}</b>
              <span className="cy-tpl-d">{t.blurb}</span>
              <span className="cy-tpl-f"><span className="cy-model-dot" style={{ background: m.hue }} /> {m.name} · ~{e.minutes[0]}–{e.minutes[1]} min</span>
            </button>
          );
        })}
      </div>
}

export function Request({ b, lead }: { b: ModBuildView; lead?: boolean }) {
  const meta = viewMeta(b);
  const atts = meta.attachments ?? [];
  const m = cyrusModel(meta.model);
  const running = !isTerminal(b.status);
  const e = running ? estimate(b.changeRequest || b.prompt, m.id, { change: !!b.changeRequest }) : null;
  return (
    <section className={`cy-doc-s ${lead ? "lead" : ""}`}>
      <h4>{b.changeRequest ? "The change you asked for" : "What you asked for"}</h4>
      <blockquote className="cy-quote">{b.changeRequest || b.prompt}</blockquote>
      {b.changeRequest && <details className="cy-details"><summary>Original description</summary><p>{b.prompt}</p></details>}
      {atts.length > 0 && (
        <div className="cy-refs">
          {atts.map((a) => (
            <a key={a.n} href={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} target="_blank" rel="noreferrer" className="cy-ref" title={a.name}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} alt={a.name} loading="lazy" />
            </a>
          ))}

