"use server";

// Admin: grant / revoke Cyrus tokens, comp a model tier, tune the economy Settings.
// Same gate as the page (/admin/cyrus-tokens): billing area AND the real signed-in
// account on the private-preview list. Every action is audit-logged.
import { notFound, redirect } from "next/navigation";
import { randomBytes } from "node:crypto";
import { db } from "../../db";
import { realUser } from "../../auth";
import { requireArea } from "../../rbac";
import { isPreviewUser } from "../../preview-access";
import { clearTokenConfigCache, CYRUS_TOKEN_DEFAULTS, TOKEN_SETTING_KEYS, loadTokenConfig, type TokenSettingKey } from "./config";
import { creditTokens, revokeTokens } from "./ledger";

const DAY = 86_400_000;
const PATH = "/admin/cyrus-tokens";

async function guard() {
  const admin = await requireArea("billing");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

async function targetUser(raw: FormDataEntryValue | null) {
  const v = String(raw ?? "").trim();
  if (!v) return null;
  return db.user.findFirst({ where: v.includes("@") ? { email: { equals: v, mode: "insensitive" } } : { id: v } });
}

const back = (q: string) => redirect(`${PATH}?${q}`);

export async function adminGrantTokens(fd: FormData) {
  const admin = await guard();
  const u = await targetUser(fd.get("user"));
  const amount = Math.floor(Number(fd.get("amount")));
  const note = String(fd.get("note") ?? "").trim().slice(0, 200);
  if (!u) back("err=" + encodeURIComponent("No such account."));
  if (!(amount > 0 && amount <= 1_000_000)) back("err=" + encodeURIComponent("Amount must be 1 to 1,000,000."));
  const cfg = await loadTokenConfig();
  const days = Math.floor(Number(fd.get("days"))) || cfg.adminGrantExpiryDays;
  const r = await creditTokens({
    userId: u!.id, amount, kind: "grant", source: "admin", sourceRef: admin.id,
    // A fresh key per submit; a double-submit within the same request id is prevented by the form token.
    idemKey: `admin:${String(fd.get("token") || randomBytes(8).toString("hex"))}`,
    expiresAt: new Date(Date.now() + Math.min(3650, Math.max(1, days)) * DAY),
    note: note || "Admin grant", actorId: admin.id,
  });
  await db.auditLog.create({ data: { userId: admin.id, action: "cyrus.tokens.grant", detail: `${u!.email} +${r.amount} ${note}`.slice(0, 500) } }).catch(() => {});
  back(r.created ? `ok=${encodeURIComponent(`Granted ${r.amount} tokens to ${u!.email}.`)}` : "ok=" + encodeURIComponent("Already applied."));
}

export async function adminRevokeTokens(fd: FormData) {
  const admin = await guard();
  const u = await targetUser(fd.get("user"));
  const amount = Math.floor(Number(fd.get("amount")));
  const note = String(fd.get("note") ?? "").trim().slice(0, 200);
  if (!u) back("err=" + encodeURIComponent("No such account."));
  if (!(amount > 0)) back("err=" + encodeURIComponent("Amount must be positive."));
  const r = await revokeTokens({ userId: u!.id, amount, idemKey: `admin-revoke:${String(fd.get("token") || randomBytes(8).toString("hex"))}`, note: note || "Admin revoke", actorId: admin.id });
  await db.auditLog.create({ data: { userId: admin.id, action: "cyrus.tokens.revoke", detail: `${u!.email} -${r.revoked} ${note}`.slice(0, 500) } }).catch(() => {});
  back(`ok=${encodeURIComponent(`Removed ${r.revoked} tokens from ${u!.email} (never below zero, never a running build's hold).`)}`);
}

export async function adminSetTierOverride(fd: FormData) {
  const admin = await guard();
  const u = await targetUser(fd.get("user"));
  const tier = String(fd.get("tier") ?? "");
  const days = Math.floor(Number(fd.get("days")));
  if (!u) back("err=" + encodeURIComponent("No such account."));
  const t = tier === "katara" || tier === "saka" || tier === "all" ? tier : null;
  const until = t && days > 0 ? new Date(Date.now() + days * DAY) : null;
  await db.cyrusTokenAccount.upsert({ where: { userId: u!.id }, create: { userId: u!.id, tierOverride: t, tierOverrideUntil: until }, update: { tierOverride: t, tierOverrideUntil: until } });
  await db.auditLog.create({ data: { userId: admin.id, action: "cyrus.tokens.tier", detail: `${u!.email} ${t ?? "none"}${until ? ` until ${until.toISOString().slice(0, 10)}` : ""}` } }).catch(() => {});
  back(`ok=${encodeURIComponent(t ? `${u!.email} now has ${t} models${until ? ` until ${until.toISOString().slice(0, 10)}` : ""}.` : `Override removed for ${u!.email}.`)}`);
}

export async function adminSaveTokenSettings(fd: FormData) {
  const admin = await guard();
  const changed: string[] = [];
  for (const k of TOKEN_SETTING_KEYS) {
    if (!fd.has(k)) continue;
    const v = String(fd.get(k) ?? "").trim();
    if (k === "cyrus_tok_reserve_table") { try { JSON.parse(v); } catch { back("err=" + encodeURIComponent("Reserve table must be valid JSON.")); } }
    const row = await db.setting.findUnique({ where: { key: k } });
    const def = CYRUS_TOKEN_DEFAULTS[k as TokenSettingKey];
    if (v === "" || v === def) { if (row) { await db.setting.delete({ where: { key: k } }); changed.push(`${k}=default`); } continue; }
    if (row?.value === v) continue;
    await db.setting.upsert({ where: { key: k }, update: { value: v }, create: { key: k, value: v } });
    changed.push(`${k}=${v.slice(0, 60)}`);
  }
  clearTokenConfigCache();
  if (changed.length) await db.auditLog.create({ data: { userId: admin.id, action: "cyrus.tokens.settings", detail: changed.join(" ").slice(0, 1000) } }).catch(() => {});
  back(`ok=${encodeURIComponent(changed.length ? `Saved ${changed.length} setting(s).` : "No changes.")}`);
}

