        </div>
        <div className="card">
          <h3 className="mb-2 text-sm font-semibold">Economy at the current settings</h3>
          <table className="w-full text-left text-sm [&_td]:px-2 [&_th]:px-2">
            <thead className="text-xs text-slate-500"><tr><th>Plan</th><th className="text-right">Price</th><th className="text-right">Tokens/mo</th><th className="text-right">AI cost if all used</th><th className="text-right">Worst-case margin</th></tr></thead>
            <tbody>
              {PLAN_TIERS.map((t) => { const m = planMargin(t, cfg); return (
                <tr key={t} className="border-t border-slate-800/40"><td className="py-1">{TIER_LABEL[t]}{prices && !prices[t] ? <span className="ml-1 text-xs text-amber-400">(no Stripe price)</span> : null}</td><td className="text-right">{usd(m.priceUsd)}</td><td className="text-right">{n(cfg.plan.tokens[t])}</td><td className="text-right">{usd(m.aiCostUsd)}</td><td className="text-right">{usd(m.marginUsd)} ({Math.round(m.marginPct * 100)}%)</td></tr>
              ); })}
            </tbody>
          </table>
          <p className="mt-3 text-xs text-slate-500">Game-server grants (initial / every renewal), monthly price:</p>
          <p className="text-xs text-slate-400">{[499, 899, 1599, 3000, 6000].map((c) => `$${(c / 100).toFixed(2)}: ${serverGrant("initial", c, 1, cfg).tokens} / +${serverGrant("renewal", c, 1, cfg).tokens}`).join(" · ")}</p>
          <p className="mt-1 text-xs text-slate-500">1 token = ${(1 / cfg.tokensPerUsd).toFixed(4)} of measured AI cost (×{cfg.mult.katara}/{cfg.mult.saka}/{cfg.mult.yakko} Katara/Saka/Yakko).</p>
        </div>
      </div>

      <div className="mb-6 grid gap-4 lg:grid-cols-3">
        <form action={adminGrantTokens} className="card flex flex-col gap-2">
          <h3 className="text-sm font-semibold">Grant tokens</h3>
