        </form>
        <form action={adminRevokeTokens} className="card flex flex-col gap-2">
          <h3 className="text-sm font-semibold">Revoke tokens</h3>
          <input type="hidden" name="token" value={token} />
          <input name="user" placeholder="email or user id" className="input" required />
          <input name="amount" type="number" min={1} placeholder="amount" className="input" required />
          <input name="note" placeholder="reason" className="input" />
          <button className="btn-primary">Revoke</button>
          <p className="text-xs text-slate-500">Never below zero; never touches tokens a running build holds.</p>
        </form>
        <form action={adminSetTierOverride} className="card flex flex-col gap-2">
          <h3 className="text-sm font-semibold">Comp a model tier</h3>
          <input name="user" placeholder="email or user id" className="input" required />
          <select name="tier" className="input" defaultValue="all"><option value="">remove override</option><option value="katara">Katara</option><option value="saka">Saka (+Katara)</option><option value="all">All models</option></select>
          <input name="days" type="number" min={1} placeholder="days (blank = no end)" className="input" />
          <button className="btn-primary">Save</button>
          <p className="text-xs text-slate-500">Unlocks models without a plan; does not add tokens.</p>
        </form>
