import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { randomBytes } from "node:crypto";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { realUser } from "@/lib/auth";
import { isPreviewUser } from "@/lib/preview-access";
import { stripeConfigured } from "@/lib/stripe";
import { CYRUS_TOKEN_DEFAULTS, PLAN_TIERS, TOKEN_SETTING_KEYS, loadTokenConfig } from "@/lib/cyrus/tokens/config";
import { planMargin, serverGrant, TIER_LABEL, effectiveTier } from "@/lib/cyrus/tokens/economy";
import { planPrices } from "@/lib/cyrus/tokens/billing";
import { adminGrantTokens, adminRevokeTokens, adminSaveTokenSettings, adminSetTierOverride } from "@/lib/cyrus/tokens/admin-actions";
import { PageHeader, Badge, StatCard, timeAgo } from "@/components/ui/primitives";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  const ok = await isPreviewUser(await realUser().catch(() => null), "modbuilder");
  return { title: ok ? "Cyrus tokens" : "Page not found", robots: { index: false, follow: false } };
}

const DAY = 86_400_000;
const n = (x: number) => Math.round(x).toLocaleString("en-US");
const usd = (x: number) => `$${x.toFixed(2)}`;

/**
 * Cyrus token economy: liability, grants, spend, AI cost vs tokens, plans, accounts, ledger,
 * manual grant/revoke/comp, and every tunable Setting. Private preview: URL-only (no nav
 * entry), billing area AND the preview allowlist, like /admin/mod-builder.
 */
export default async function AdminCyrusTokensPage({ searchParams }: { searchParams: Promise<Record<string, string | undefined>> }) {
  await requireArea("billing");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  const sp = await searchParams;
  const cfg = await loadTokenConfig(true);
  const now = new Date();
  const since = new Date(now.getTime() - 30 * DAY);
  const live = { remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: now } }] };
  const [outstanding, bySource, held, granted30, spent30, cost30, plans, accounts, ledger, settings, prices] = await Promise.all([
    db.cyrusTokenLot.aggregate({ where: live, _sum: { remaining: true } }),
    db.cyrusTokenLot.groupBy({ by: ["source"], where: live, _sum: { remaining: true } }),
    db.cyrusTokenReservation.aggregate({ where: { status: "held" }, _sum: { amount: true }, _count: { _all: true } }),
    db.cyrusTokenLedger.groupBy({ by: ["source"], where: { kind: { in: ["grant", "purchase"] }, createdAt: { gt: since } }, _sum: { delta: true }, _count: { _all: true } }),
    db.cyrusTokenLedger.aggregate({ where: { kind: "spend", createdAt: { gt: since } }, _sum: { delta: true }, _count: { _all: true } }),
    db.cyrusTokenReservation.aggregate({ where: { settledAt: { gt: since } }, _sum: { costUsd: true, charged: true } }),
    db.cyrusPlan.findMany({ orderBy: { updatedAt: "desc" }, take: 200 }),
    db.cyrusTokenAccount.findMany({ orderBy: { balance: "desc" }, take: 100 }),
    db.cyrusTokenLedger.findMany({ orderBy: { createdAt: "desc" }, take: 80 }),
    db.setting.findMany({ where: { key: { startsWith: "cyrus_tok_" } } }),
    stripeConfigured() ? planPrices(cfg).catch(() => null) : Promise.resolve(null),
  ]);
  const ids = Array.from(new Set([...accounts.map((a) => a.userId), ...ledger.map((l) => l.userId), ...plans.map((p) => p.userId)]));
  const users = await db.user.findMany({ where: { id: { in: ids } }, select: { id: true, email: true } });
  const email = new Map(users.map((u) => [u.id, u.email]));
  const planBy = new Map(plans.map((p) => [p.userId, p]));
  const stored = new Map(settings.map((s) => [s.key, s.value]));
  const liabilityTokens = outstanding._sum.remaining ?? 0;
  const liabilityUsd = liabilityTokens / cfg.tokensPerUsd;
  const activePlans = plans.filter((p) => effectiveTier({ plan: p, now, cfg }) !== "free");
  const mrrCents = activePlans.reduce((a, p) => a + (prices?.[p.priceTier as "katara"]?.unitAmount ?? cfg.plan.cents[p.priceTier as "katara"] ?? 0), 0);
  const cost = cost30._sum.costUsd ?? 0;
  const charged = cost30._sum.charged ?? 0;
  const token = randomBytes(8).toString("hex");

  return (
    <div>
      <PageHeader title="Cyrus tokens" sub="Private preview. Token liability, grants, spend against real AI cost, plans, and every tunable number.">
        {cfg.live ? <Badge tone="green">live for everyone</Badge> : <Badge tone="amber">preview accounts only</Badge>}
        {cfg.enforce ? <Badge tone="brand">enforced</Badge> : <Badge tone="slate">tracking only</Badge>}
        {stripeConfigured() ? (Object.values(prices ?? {}).some((p) => p?.livemode) ? <Badge tone="red">Stripe LIVE prices</Badge> : <Badge tone="slate">Stripe test prices</Badge>) : <Badge tone="slate">Stripe off</Badge>}
      </PageHeader>
      {sp.ok && <p className="mb-4 rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{sp.ok}</p>}
      {sp.err && <p className="mb-4 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{sp.err}</p>}

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Outstanding tokens (liability)" value={n(liabilityTokens)} delta={`≈ ${usd(liabilityUsd)} AI cost if all spent`} />
        <StatCard label="Held by running builds" value={n(held._sum.amount ?? 0)} delta={`${held._count._all} build(s)`} />
        <StatCard label="Spent, 30 days" value={n(-(spent30._sum.delta ?? 0))} delta={`${spent30._count._all} builds · AI cost ${usd(cost)} · ${charged ? `${(charged / Math.max(cost, 1e-9)).toFixed(0)} tokens/$` : "–"}`} />
        <StatCard label="Active plans" value={String(activePlans.length)} delta={`MRR ${usd(mrrCents / 100)}`} />
      </div>

      <div className="mb-6 grid gap-4 lg:grid-cols-2">
        <div className="card">
          <h3 className="mb-2 text-sm font-semibold">Outstanding by source · granted last 30 days</h3>
          <table className="w-full text-left text-sm [&_td]:px-2 [&_th]:px-2">
            <thead className="text-xs text-slate-500"><tr><th>Source</th><th className="text-right">Outstanding</th><th className="text-right">Granted 30d</th><th className="text-right">Grants</th></tr></thead>
            <tbody>
              {["server_initial", "server_renewal", "plan", "topup", "admin", "refund"].map((s) => {
                const o = bySource.find((x) => x.source === s)?._sum.remaining ?? 0;
                const g = granted30.find((x) => x.source === s);
                return <tr key={s} className="border-t border-slate-800/40"><td className="py-1">{s}</td><td className="text-right">{n(o)}</td><td className="text-right">{n(g?._sum.delta ?? 0)}</td><td className="text-right">{g?._count._all ?? 0}</td></tr>;
              })}
            </tbody>
          </table>
        </div>
        <div className="card">
          <h3 className="mb-2 text-sm font-semibold">Economy at the current settings</h3>
          <table className="w-full text-left text-sm [&_td]:px-2 [&_th]:px-2">
            <thead className="text-xs text-slate-500"><tr><th>Plan</th><th className="text-right">Price</th><th className="text-right">Tokens/mo</th><th className="text-right">AI cost if all used</th><th className="text-right">Worst-case margin</th></tr></thead>
            <tbody>
              {PLAN_TIERS.map((t) => { const m = planMargin(t, cfg); return (
                <tr key={t} className="border-t border-slate-800/40"><td className="py-1">{TIER_LABEL[t]}{prices && !prices[t] ? <span className="ml-1 text-xs text-amber-400">(no Stripe price)</span> : null}</td><td className="text-right">{usd(m.priceUsd)}</td><td className="text-right">{n(cfg.plan.tokens[t])}</td><td className="text-right">{usd(m.aiCostUsd)}</td><td className="text-right">{usd(m.marginUsd)} ({Math.round(m.marginPct * 100)}%)</td></tr>
              ); })}
            </tbody>
          </table>
          <p className="mt-3 text-xs text-slate-500">Game-server grants (initial / every renewal), monthly price:</p>
          <p className="text-xs text-slate-400">{[499, 899, 1599, 3000, 6000].map((c) => `$${(c / 100).toFixed(2)}: ${serverGrant("initial", c, 1, cfg).tokens} / +${serverGrant("renewal", c, 1, cfg).tokens}`).join(" · ")}</p>
          <p className="mt-1 text-xs text-slate-500">1 token = ${(1 / cfg.tokensPerUsd).toFixed(4)} of measured AI cost (×{cfg.mult.katara}/{cfg.mult.saka}/{cfg.mult.yakko} Katara/Saka/Yakko).</p>
        </div>
      </div>

      <div className="mb-6 grid gap-4 lg:grid-cols-3">
        <form action={adminGrantTokens} className="card flex flex-col gap-2">
          <h3 className="text-sm font-semibold">Grant tokens</h3>
          <input type="hidden" name="token" value={token} />
          <input name="user" placeholder="email or user id" className="input" required />
          <input name="amount" type="number" min={1} placeholder="amount" className="input" required />
          <input name="days" type="number" min={1} placeholder={`expires in days (${cfg.adminGrantExpiryDays})`} className="input" />
          <input name="note" placeholder="note (shown in the customer's history)" className="input" />
          <button className="btn-primary">Grant</button>
        </form>
        <form action={adminRevokeTokens} className="card flex flex-col gap-2">
          <h3 className="text-sm font-semibold">Revoke tokens</h3>
          <input type="hidden" name="token" value={token} />
          <input name="user" placeholder="email or user id" className="input" required />
          <input name="amount" type="number" min={1} placeholder="amount" className="input" required />
          <input name="note" placeholder="reason" className="input" />
          <button className="btn-primary">Revoke</button>
          <p className="text-xs text-slate-500">Never below zero; never touches tokens a running build holds.</p>
        </form>
        <form action={adminSetTierOverride} className="card flex flex-col gap-2">
          <h3 className="text-sm font-semibold">Comp a model tier</h3>
          <input name="user" placeholder="email or user id" className="input" required />
          <select name="tier" className="input" defaultValue="all"><option value="">remove override</option><option value="katara">Katara</option><option value="saka">Saka (+Katara)</option><option value="all">All models</option></select>
          <input name="days" type="number" min={1} placeholder="days (blank = no end)" className="input" />
          <button className="btn-primary">Save</button>
          <p className="text-xs text-slate-500">Unlocks models without a plan; does not add tokens.</p>
        </form>
      </div>

      <div className="card mb-6 overflow-x-auto">
        <h3 className="mb-2 text-sm font-semibold">Accounts (top 100 by balance)</h3>
        {accounts.length === 0 ? <p className="text-sm text-slate-500">No token accounts yet.</p> : (
          <table className="w-full text-left text-sm [&_td]:px-2 [&_th]:px-2">
            <thead className="text-xs text-slate-500"><tr><th>Account</th><th className="text-right">Balance</th><th className="text-right">Held</th><th>Models</th><th>Plan</th><th className="text-right">Granted</th><th className="text-right">Spent</th></tr></thead>
            <tbody>
              {accounts.map((a) => { const p = planBy.get(a.userId); const tier = effectiveTier({ plan: p ?? null, override: a.tierOverride, overrideUntil: a.tierOverrideUntil, now, cfg }); return (
                <tr key={a.userId} className="border-t border-slate-800/40">
                  <td className="py-1">{email.get(a.userId) ?? a.userId}</td><td className="text-right">{n(a.balance)}</td><td className="text-right">{n(a.reserved)}</td>
                  <td>{TIER_LABEL[tier]}{a.tierOverride ? <span className="ml-1 text-xs text-amber-400">comp</span> : null}</td>
                  <td>{p ? `${p.priceTier} · ${p.status}${p.cancelAtPeriodEnd ? " · cancels" : ""}${p.livemode ? "" : " · test"}` : "–"}</td>
                  <td className="text-right">{n(a.lifetimeGranted)}</td><td className="text-right">{n(a.lifetimeSpent)}</td>
                </tr>
              ); })}
            </tbody>
          </table>
        )}
      </div>

      <div className="card mb-6 overflow-x-auto">
        <h3 className="mb-2 text-sm font-semibold">Ledger (latest 80, append-only)</h3>
        <table className="w-full text-left text-xs [&_td]:px-2 [&_th]:px-2">
          <thead className="text-slate-500"><tr><th>When</th><th>Account</th><th>Kind</th><th className="text-right">Δ</th><th className="text-right">Balance</th><th>Source</th><th>Ref / build</th><th>Note</th></tr></thead>
          <tbody>
            {ledger.map((l) => (
              <tr key={l.id} className="border-t border-slate-800/40 align-top">
                <td className="py-1 whitespace-nowrap">{timeAgo(l.createdAt)}</td><td>{email.get(l.userId) ?? l.userId}</td><td>{l.kind}</td>
                <td className={`text-right ${l.delta > 0 ? "text-emerald-400" : l.delta < 0 ? "text-rose-300" : ""}`}>{l.delta > 0 ? "+" : ""}{n(l.delta)}</td>
                <td className="text-right">{n(l.balanceAfter)}</td><td>{l.source ?? (l.model ? `build · ${l.model}` : "")}</td>
                <td className="max-w-[220px] truncate font-mono">{l.buildId ?? l.sourceRef ?? ""}</td><td>{l.note ?? ""}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <form action={adminSaveTokenSettings} className="card">
        <h3 className="mb-1 text-sm font-semibold">Settings</h3>
        <p className="mb-3 text-xs text-slate-500">Blank or equal to the default = use the default. Recommended values and reasoning: docs “Cyrus token economy”. Saved values apply within 30 seconds.</p>
        <div className="grid gap-x-4 gap-y-2 md:grid-cols-2">
          {TOKEN_SETTING_KEYS.map((k) => (
            <label key={k} className="flex flex-col gap-1 text-xs">
              <span className="font-mono text-slate-400">{k} <span className="text-slate-600">default {k === "cyrus_tok_reserve_table" ? "(JSON)" : JSON.stringify(CYRUS_TOKEN_DEFAULTS[k])}</span></span>
              {k === "cyrus_tok_reserve_table"
                ? <textarea name={k} defaultValue={stored.get(k) ?? CYRUS_TOKEN_DEFAULTS[k]} rows={4} className="input font-mono text-xs" />
                : <input name={k} defaultValue={stored.get(k) ?? ""} placeholder={CYRUS_TOKEN_DEFAULTS[k]} className={`input text-xs ${stored.has(k) ? "border-violet-400/40" : ""}`} />}
            </label>
          ))}
        </div>
        <button className="btn-primary mt-4">Save settings</button>
      </form>
    </div>
  );
}

