// LOCAL MOCK of the Mod Builder build service, for Cyrus UI screenshots only.
// Serves REAL build records + sources fetched read-only from the service (fx/), and
// simulates new builds by replaying a real fixture's files: v2 adds the 0.4 live view
// (/live with a streaming draft, /source of the in-progress workspace).
// Control: POST /_set {id, status, fx?, ago?, livePct?, run?} freezes (or runs) a build at a stage.
"use strict";
const http = require("http");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const FX = path.join(__dirname, "fx");
const PORT = 7399;
const now = () => new Date().toISOString();
const iso = (ms) => new Date(ms).toISOString();

const fixtures = {};
for (const f of fs.readdirSync(FX)) if (f.endsWith(".json")) { const d = JSON.parse(fs.readFileSync(path.join(FX, f))); fixtures[d.id] = d; }
const recs = new Map();

function fixtureFor(prompt, changeRequest) {
  const p = (prompt + " " + (changeRequest || "")).toLowerCase();
  if (changeRequest && /heal|feed/.test(p)) return "p0-heal01c1";
  if (changeRequest && /streak|daily/.test(p)) return "mb16f8378db9c3e2b68cbe";
  if (/econom|coin|shop/.test(p)) return "p0-econ01";
  if (/scoreboard|sidebar|stats/.test(p)) return "p0-score01";
  if (/spleef/.test(p)) return "p0-spleef01";
  if (/zone|grief/.test(p)) return "p0-zones01";
  if (/boss/.test(p)) return "mb900780697eb88bcaaede";
  if (/streak|daily/.test(p)) return "mb67f7a97b866da50800f4";
  if (/join|welcome/.test(p)) return "p0-joinmsg01";

