  if (st === "succeeded") return { ...fixtures[fxId], id: e.id, prompt: body.prompt, changeRequest: body.changeRequest || null, baseBuildId: body.baseBuildId || null, mcVersion: body.mcVersion, durationMs: Math.round(tl.scanEnd * 1000), finishedAt: iso(t0 + tl.scanEnd * 1000), queuePosition: 0, references: e.references || [] };
  const ev = [{ at: iso(t0), stage: "queued", message: "Waiting for a free builder" }];
  if (s >= 1.5) ev.push({ at: iso(t0 + 1500), stage: "planning", message: body.baseBuildId ? "Reading your existing plugin and planning the change" : "Planning the plugin from your description" });
  if (s >= 2 && e.references?.length) ev.push({ at: iso(t0 + 2000), stage: "planning", message: "Reading 1.png" });
  if (s >= 4) ev.push({ at: iso(t0 + 4000), stage: "coding", message: "Writing the plugin code" });
  for (const w of tl.writes) if (s >= w.t1) ev.push({ at: iso(t0 + w.t1 * 1000), stage: "coding", message: `${body.baseBuildId ? "Edited" : "Wrote"} ${w.path.split("/").pop()}` });
  if (s >= tl.codingEnd) ev.push({ at: iso(t0 + tl.codingEnd * 1000), stage: "compiling", message: `Compiling against Paper ${body.mcVersion}` });
  if (s >= tl.compileEnd) { ev.push({ at: iso(t0 + tl.compileEnd * 1000 - 200), stage: "compiling", message: "Compiled successfully" }); ev.push({ at: iso(t0 + tl.compileEnd * 1000), stage: "scanning", message: "Running the safety check" }); }
  return {
    id: e.id, status: st, prompt: body.prompt, changeRequest: body.changeRequest || null, baseBuildId: body.baseBuildId || null, mcVersion: body.mcVersion,
    error: null, errorCode: null, attempts: 1, repairs: 0, costUsd: 0.1, durationMs: 0, pluginName: null, references: e.references || [],
    jar: null, summary: null, commands: [], permissions: [], config: [], warnings: [], files: [], safety: null, events: ev, queuePosition: st === "queued" ? 1 : 0, finishedAt: null,
  };
}
const elapsed = (e) => (e.frozen !== undefined ? e.frozen : (Date.now() - e.t0) / 1000);
function liveView(e, q) {
  const s = elapsed(e);
  const st = stageAt(e.tl, s);
  if (st === "succeeded") return { live: false, status: st, files: [], draft: null };
  const done = e.tl.writes.filter((w) => s >= w.t1);
  const cur = e.tl.writes.find((w) => s >= w.t0 && s < w.t1);
  const files = done.map((w) => ({ path: w.path, size: Buffer.byteLength(w.text), hash: crypto.createHash("sha1").update(w.text).digest("hex").slice(0, 12) }));
  let draft = null;
  if (cur) {
    const n = Math.floor(cur.text.length * Math.min(1, (s - cur.t0) / (cur.t1 - cur.t0)));
    const seq = e.tl.writes.indexOf(cur) + 1;
    const from = q.get("draft") === cur.path && Number(q.get("seq")) === seq ? Math.min(n, Number(q.get("from") || 0)) : 0;
    draft = { path: cur.path, op: "write", seq, from, text: cur.text.slice(from, n), total: n, done: false, inputBytes: n };
  }
  return { live: true, status: st, files, draft };
}

const send = (res, code, body) => { res.writeHead(code, { "Content-Type": "application/json" }); res.end(JSON.stringify(body)); };
const readBody = (req) => new Promise((r) => { let b = ""; req.on("data", (d) => (b += d)); req.on("end", () => { try { r(JSON.parse(b || "{}")); } catch { r({}); } }); });

function get(id) {
  if (recs.has(id)) return recs.get(id);
  if (fixtures[id]) { const e = { id, static: fixtures[id], fx: id }; recs.set(id, e); return e; }
  return null;
}
const recOf = (e) => (e.static ? e.static : record(e, elapsed(e)));

http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const parts = url.pathname.split("/").filter(Boolean);
  if (url.pathname === "/health") return send(res, 200, { ok: true, service: "mock", image: "0.4-mock", features: { images: true, live: true } });
  if (req.method === "POST" && url.pathname === "/_set") {
