    if (b.status === "failed") { recs.set(b.id, { id: b.id, fx: fxId, static: { ...fixtures[b.fx], id: b.id } }); return send(res, 200, { ok: true }); }
    const tl = timeline(fxId);
    const e = { id: b.id, body: b, fxId, fx: fxId, tl, t0: Date.now() - (b.ago || 30) * 1000, references: b.references || [] };

