// Cyrus tokens end-to-end in Stripe TEST mode against the local dev server (:3157),
// throwaway DB nxeon_agt_cyrustokens and the local mock build service (:7398).
// usage: node e2e.mjs <step...>   steps: home plan topup build locked upgrade other checkout history
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire("/opt/nxeon/node_modules/");
const { chromium } = require("playwright");
const tok = JSON.parse(readFileSync(new URL("./tokens.json", import.meta.url), "utf8"));
const BASE = process.env.BASE ?? "http://localhost:3157";
const OUT = "/root/agent-notes/cyrus-economy/shots";
mkdirSync(OUT, { recursive: true });
const steps = process.argv.slice(2);
const log = (...a) => console.log(new Date().toISOString().slice(11, 19), ...a);

const browser = await chromium.launch();
async function ctxFor(who = "ownerTok", view = { width: 1440, height: 900 }) {
  const ctx = await browser.newContext({ viewport: view, deviceScaleFactor: 1, colorScheme: "dark" });
  await ctx.addCookies([{ name: tok.cookie, value: tok[who], url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript(() => { try { localStorage.setItem("nx-theme", "dark"); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} });
  page.on("pageerror", (e) => log("PAGEERROR", String(e).slice(0, 300)));
  return { ctx, page };
}
const state = async (page) => page.evaluate(() => fetch("/api/cyrus/tokens", { cache: "no-store" }).then((r) => r.json()));
const shot = (page, n) => page.screenshot({ path: `${OUT}/${n}.png` }).then(() => log("shot", n));
async function dismiss(page) {
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later"]) {
    const b = page.getByRole("button", { name: label, exact: true });
    if (await b.count().catch(() => 0)) await b.first().click({ timeout: 800 }).catch(() => {});
  }
}
async function openCyrus(page) {
  await page.goto(BASE + "/dashboard/cyrus", { waitUntil: "domcontentloaded", timeout: 300000 });
  await page.waitForSelector(".cyt-chip", { timeout: 120000 });
  await dismiss(page);
  await page.waitForTimeout(1500);
}
async function payCard(page) {
  // Stripe Payment Element (custom checkout) iframe: card number / expiry / cvc (+country/postal).
  await page.waitForSelector(".cyt-card iframe", { timeout: 60000 });
  const fr = page.frameLocator(".cyt-card iframe").first();
  await fr.locator('input[name="number"]').fill("4242424242424242", { timeout: 60000 });
  await fr.locator('input[name="expiry"]').fill("12 / 34");
  await fr.locator('input[name="cvc"]').fill("123");
  const postal = fr.locator('input[name="postalCode"]');
  if (await postal.count()) await postal.fill("10001").catch(() => {});
  await page.waitForTimeout(800);
  await page.locator(".cyt-pay-go").click();
  await page.waitForURL(/\/dashboard\/cyrus/, { timeout: 120000 });
  await page.waitForURL((u) => !u.searchParams.has("session_id"), { timeout: 120000 });
}
async function waitBalance(page, pred, ms = 60000) {
  const t0 = Date.now();
  for (;;) {
    const s = await state(page);
    if (pred(s)) return s;
    if (Date.now() - t0 > ms) throw new Error("balance wait timed out: " + JSON.stringify({ b: s.balance, tier: s.tier }));
    await page.waitForTimeout(2000);
  }
}

const { page } = await ctxFor();
try {
  for (const step of steps) {
    log("== step", step);
    if (step === "home") {
      await openCyrus(page);
      log("state", JSON.stringify(await state(page)).slice(0, 400));
      await shot(page, "01-home-chip");
      await page.locator(".cyt-chip").first().click();
      await page.waitForSelector(".cyt-modal");
      await page.waitForTimeout(800);
      await shot(page, "02-modal-plans-noplan");
    }
    if (step === "plan") {
      await openCyrus(page);
      const before = (await state(page)).balance;
      await page.locator(".cyt-chip").first().click();
      await page.getByRole("button", { name: "Get Katara" }).click();
      await page.waitForSelector(".cyt-card iframe", { timeout: 60000 });
      await page.waitForTimeout(2500);
      await shot(page, "03-plan-checkout");
      await payCard(page);
      await page.waitForTimeout(1500);
      await shot(page, "04-after-plan-notice");
      const s = await waitBalance(page, (x) => x.balance >= before + 750);
      log("after plan", s.balance, s.tier, JSON.stringify(s.plan));
    }
    if (step === "topup") {
      await openCyrus(page);
      const before = (await state(page)).balance;
      await page.locator(".cyt-chip").first().click();
      await page.getByRole("tab", { name: "Top up" }).click();
      await page.locator(".cyt-amt-in input").fill("10");
      await page.waitForTimeout(400);
      await shot(page, "05-topup");
      await page.getByRole("button", { name: /^Pay \$10/ }).click();
      await payCard(page);
      const s = await waitBalance(page, (x) => x.balance >= before + 1200);
      log("after topup", s.balance);
    }
    if (step === "locked") {
      await openCyrus(page);
      await page.locator(".cy-home textarea").fill("A boss fight: a giant zombie boss with three phases, minions every 30 seconds, a boss bar and a reward chest");
      await page.locator(".cy-pick", { hasText: /Katara|Saka|Yakko/ }).first().click();
      await page.waitForTimeout(400);
      await shot(page, "06-model-picker-locks");
      await page.locator(".cy-opt", { hasText: "Yakko" }).click();
      await page.waitForTimeout(400);
      await shot(page, "07-estimate-yakko-locked");
      await page.locator(".cy-go").click();
      await page.waitForSelector(".cyt-reason", { timeout: 30000 });
      await page.waitForTimeout(600);
      await shot(page, "08-model-locked-modal");
      await page.keyboard.press("Escape");
    }
    if (step === "build") {
      await openCyrus(page);
      const before = await state(page);
      await page.locator(".cy-home textarea").fill("A /heal command that fully heals the player and feeds them, with a 60 second cooldown");
      await page.locator(".cy-pick", { hasText: /Katara|Saka|Yakko/ }).first().click();
      await page.locator(".cy-opt", { hasText: "Katara" }).click();
      await page.waitForTimeout(500);
      await shot(page, "09-estimate-katara");
      await page.locator(".cy-go").click();
      await page.waitForURL(/\/dashboard\/cyrus\/mb/, { timeout: 60000 });
      await page.waitForTimeout(2500);
      const mid = await state(page);
      log("during build", mid.balance, "reserved", mid.reserved, "available", mid.available);
      await shot(page, "10-building-held");
      const s = await waitBalance(page, (x) => x.reserved === 0 && x.balance < before.balance, 180000);
      log("after build", before.balance, "->", s.balance, "spent", before.balance - s.balance);
      await page.waitForTimeout(1500);
      await shot(page, "11-built");
    }
    if (step === "upgrade") {
      await openCyrus(page);
      const before = await state(page);
      await page.locator(".cyt-chip").first().click();
      await page.getByRole("button", { name: "Upgrade to All models" }).click();
      await shot(page, "12-upgrade-confirm");
      await page.getByRole("button", { name: "Upgrade", exact: true }).click();
      await page.waitForSelector(".cyt-ok", { timeout: 90000 });
      const s = await waitBalance(page, (x) => x.tier === "all" && x.balance > before.balance);
      log("after upgrade", before.balance, "->", s.balance, s.tier, JSON.stringify(s.models));
      await page.waitForTimeout(800);
      await shot(page, "13-upgraded");
    }
    if (step === "history") {
      await openCyrus(page);
      await page.locator(".cyt-chip").first().click();
      await page.getByRole("tab", { name: "History" }).click();
      await page.waitForSelector(".cyt-hist li", { timeout: 30000 });
      await page.waitForTimeout(600);
      await shot(page, "14-history");
    }
    if (step === "mobile") {
      const m = await ctxFor("ownerTok", { width: 390, height: 844 });
      await openCyrus(m.page);
      await shot(m.page, "15-mobile-home");
      await m.page.locator(".cyt-chip").first().click();
      await m.page.waitForTimeout(800);
      await shot(m.page, "16-mobile-modal");
      await m.ctx.close();
    }
    if (step === "other") {
      const o = await ctxFor("otherTok");
      const r1 = await o.page.goto(BASE + "/dashboard/cyrus", { waitUntil: "domcontentloaded", timeout: 300000 });
      const r2 = await o.page.evaluate(() => Promise.all(["/api/cyrus/tokens", "/api/cyrus/tokens/checkout-line?monthlyCents=899&termMonths=1"].map((u) => fetch(u).then((r) => r.status))));
      log("non-preview account: /dashboard/cyrus", r1?.status(), "api", JSON.stringify(r2));
      await o.ctx.close();
    }
    if (step === "checkout") {
      const r = await page.evaluate(() => fetch("/api/cyrus/tokens/checkout-line?monthlyCents=899&termMonths=1").then((r) => r.json()));
      log("owner checkout line", JSON.stringify(r));
    }
  }
} catch (e) {
  log("FAILED", e.message);
  await shot(page, "zz-failure").catch(() => {});
  process.exitCode = 1;
}
await browser.close();

