// REAL Stripe TEST-mode proof of plan stacking, replays, upgrade proration, refund, cancel,
// against the throwaway DB. Uses a Stripe Test Clock to make a real monthly renewal happen.
// Refuses anything but an sk_test_ key and the *_cyrustokens DB.
import Stripe from "stripe";
import { db } from "../lib/db";
import { reconcileSubscription, handleCyrusStripeEvent, changePlan, setCancelAtPeriodEnd, planPrices } from "../lib/cyrus/tokens/billing";
import { tokenSummary } from "../lib/cyrus/tokens/ledger";
import { tierOf } from "../lib/cyrus/tokens/access";

const key = process.env.STRIPE_SECRET_KEY || "";
if (!key.startsWith("sk_test_")) throw new Error("refusing: TEST key only");
if (!/_cyrustokens$/.test(process.env.DATABASE_URL || "")) throw new Error("refusing: throwaway DB only");
const stripe = new Stripe(key);
const log = (...a: unknown[]) => console.log(new Date().toISOString().slice(11, 19), ...a);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const bal = async (u: string) => (await tokenSummary(u)).balance;

async function clockReady(id: string) {
  for (let i = 0; i < 90; i++) { const c = await stripe.testHelpers.testClocks.retrieve(id); if (c.status === "ready") return c; await sleep(2000); }
  throw new Error("test clock never ready");
}
async function replayAll(since: number, ids: Set<string>) {
  // Every real event Stripe generated for this customer/subscription, replayed TWICE.
  const evs: Stripe.Event[] = [];
  for await (const e of stripe.events.list({ created: { gte: since }, limit: 100 })) {
    const o = e.data.object as unknown as Record<string, unknown>;
    const s = JSON.stringify(o);
    if ([...ids].some((id) => s.includes(id))) evs.push(e);
    if (evs.length > 200) break;
  }
  const types = new Map<string, number>();
  for (let pass = 0; pass < 2; pass++) for (const e of evs.reverse()) { await handleCyrusStripeEvent(e); if (!pass) types.set(e.type, (types.get(e.type) ?? 0) + 1); }
  return Object.fromEntries(types);
}

async function main() {
  const since = Math.floor(Date.now() / 1000) - 5;
  const prices = await planPrices();
  log("prices", Object.fromEntries(Object.entries(prices).map(([k, v]) => [k, v && `${v.id} ${v.unitAmount} live=${v.livemode}`])));
  const user = await db.user.create({ data: { email: `cyt-clock-${Date.now()}@example.test`, passwordHash: "x", name: "Clock Test" } });
  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: Math.floor(Date.now() / 1000), name: `cyrus-tokens-${user.id}` });
  const customer = await stripe.customers.create({ email: user.email, test_clock: clock.id, metadata: { nxeonUserId: user.id } });
  const pm = await stripe.paymentMethods.attach("pm_card_visa", { customer: customer.id });
  await stripe.customers.update(customer.id, { invoice_settings: { default_payment_method: pm.id } });
  await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customer.id } });
  const sub = await stripe.subscriptions.create({ customer: customer.id, items: [{ price: prices.katara!.id }], metadata: { cyrusUserId: user.id, cyrusTier: "katara" }, default_payment_method: pm.id });
  log("subscription", sub.id, sub.status, "clock", clock.id);
  await reconcileSubscription(sub.id);
  log("after first invoice: balance", await bal(user.id), "tier", await tierOf(user.id));

  // Advance one month + a day: Stripe really bills the renewal on card 4242 (pm_card_visa).
  const t1 = Math.floor(Date.now() / 1000) + 32 * 86400;
  await stripe.testHelpers.testClocks.advance(clock.id, { frozen_time: t1 });
  await clockReady(clock.id);
  for (let i = 0; i < 30; i++) {
    const inv = await stripe.invoices.list({ subscription: sub.id, status: "paid", limit: 5 });
    if (inv.data.length >= 2) break;
    await sleep(2000);
  }
  await reconcileSubscription(sub.id);
  log("after renewal (stacked): balance", await bal(user.id));
  const r1 = await replayAll(since, new Set([sub.id, customer.id]));
  log("replayed real events x2:", JSON.stringify(r1), "balance", await bal(user.id));

  // Upgrade to All models: real proration invoice charged now.
  const up = await changePlan(user as never, "all");
  log("upgrade:", JSON.stringify(up), "balance", await bal(user.id), "tier", await tierOf(user.id));

  // Refund the renewal invoice's payment in full: its unspent tokens come back off.
  const paid = await stripe.invoices.list({ subscription: sub.id, status: "paid", limit: 10 });
  const renewal = paid.data.find((i) => i.billing_reason === "subscription_cycle");
  const ip = renewal ? await stripe.invoicePayments.list({ invoice: renewal.id!, limit: 1 }) : null;
  const pi = ip?.data[0]?.payment?.payment_intent as string | undefined;
  if (pi) {
    const refund = await stripe.refunds.create({ payment_intent: typeof pi === "string" ? pi : (pi as { id: string }).id });
    log("refund", refund.id, refund.status);
    await sleep(3000);
    const piObj = await stripe.paymentIntents.retrieve(typeof pi === "string" ? pi : (pi as { id: string }).id, { expand: ["latest_charge"] });
    const ch = piObj.latest_charge as Stripe.Charge;
    await handleCyrusStripeEvent({ id: "evt_manual", type: "charge.refunded", data: { object: ch } } as unknown as Stripe.Event);
    await handleCyrusStripeEvent({ id: "evt_manual2", type: "charge.refunded", data: { object: ch } } as unknown as Stripe.Event);
    log("after refund of the renewal (x2): balance", await bal(user.id));
  }

  // Cancel at period end, then end it.
  await setCancelAtPeriodEnd(user as never, true);
  log("cancel at period end:", JSON.stringify(await db.cyrusPlan.findUnique({ where: { userId: user.id }, select: { status: true, cancelAtPeriodEnd: true, tier: true, priceTier: true, currentPeriodEnd: true } })));
  const t2 = t1 + 32 * 86400;
  await stripe.testHelpers.testClocks.advance(clock.id, { frozen_time: t2 });
  await clockReady(clock.id);
  await reconcileSubscription(sub.id);
  const p = await db.cyrusPlan.findUnique({ where: { userId: user.id } });
  const lot = await db.cyrusTokenLot.findFirst({ where: { userId: user.id, source: "plan" }, orderBy: { createdAt: "desc" } });
  log("after period end:", p?.status, "endedAt", p?.endedAt?.toISOString(), "tier now", await tierOf(user.id), "plan lot expires", lot?.expiresAt?.toISOString());
  const rows = await db.cyrusTokenLedger.findMany({ where: { userId: user.id }, orderBy: { createdAt: "asc" }, select: { kind: true, delta: true, balanceAfter: true, idemKey: true, note: true } });
  for (const r of rows) log("  ledger", r.kind.padEnd(8), String(r.delta).padStart(6), String(r.balanceAfter).padStart(6), r.idemKey, r.note ?? "");
  await stripe.testHelpers.testClocks.del(clock.id).catch(() => {});
  log("test clock deleted");
}
main().catch((e) => { console.error(e); process.exitCode = 1; }).finally(() => db.$disconnect());

