// Replays the REAL Stripe TEST-mode events of the owner's Cyrus purchases through the real
// HTTP webhook route (signature-verified with the local secret), twice, and shows the
// balance does not move. Throwaway DB + test key only.
import Stripe from "stripe";
import { readFileSync } from "node:fs";
import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();
const key = process.env.STRIPE_SECRET_KEY || "";
if (!key.startsWith("sk_test_") || !/_cyrustokens$/.test(process.env.DATABASE_URL || "")) throw new Error("refusing");
const stripe = new Stripe(key);
const secret = readFileSync(__dirname + "/whsec", "utf8").trim();
const BASE = process.env.BASE ?? "http://localhost:3157";

async function balance(userId: string) {
  const a = await db.cyrusTokenLot.aggregate({ where: { userId, remaining: { gt: 0 } }, _sum: { remaining: true } });
  return a._sum.remaining ?? 0;
}
async function main() {
  const owner = await db.user.findFirstOrThrow({ where: { email: "nicholas.sj.albanese@gmail.com" } });
  if (!owner.stripeCustomerId) throw new Error("owner has no test customer yet");
  const plan = await db.cyrusPlan.findUnique({ where: { userId: owner.id } });
  const ids = [owner.stripeCustomerId, plan?.stripeSubscriptionId].filter(Boolean) as string[];
  const evs: Stripe.Event[] = [];
  for await (const e of stripe.events.list({ created: { gte: Math.floor(Date.now() / 1000) - 3 * 3600 }, limit: 100 })) {
    if (ids.some((id) => JSON.stringify(e.data.object).includes(id))) evs.push(e);
    if (evs.length > 300) break;
  }
  const before = await balance(owner.id);
  const ledgerBefore = await db.cyrusTokenLedger.count({ where: { userId: owner.id } });
  const codes: Record<string, number> = {};
  for (let pass = 0; pass < 2; pass++) {
    for (const e of [...evs].reverse()) {
      const payload = JSON.stringify(e);
      const header = stripe.webhooks.generateTestHeaderString({ payload, secret });
      const r = await fetch(`${BASE}/api/stripe/webhook`, { method: "POST", headers: { "stripe-signature": header, "content-type": "application/json" }, body: payload });
      codes[r.status] = (codes[r.status] ?? 0) + 1;
    }
  }
  const bad = await fetch(`${BASE}/api/stripe/webhook`, { method: "POST", headers: { "stripe-signature": "t=1,v1=deadbeef" }, body: JSON.stringify(evs[0] ?? {}) });
  const types = evs.reduce<Record<string, number>>((a, e) => ((a[e.type] = (a[e.type] ?? 0) + 1), a), {});
  console.log(JSON.stringify({ events: evs.length, types, http: codes, forgedSignature: bad.status, balanceBefore: before, balanceAfter: await balance(owner.id), ledgerRowsBefore: ledgerBefore, ledgerRowsAfter: await db.cyrusTokenLedger.count({ where: { userId: owner.id } }), walletBalanceCents: (await db.user.findUnique({ where: { id: owner.id }, select: { balanceCents: true } }))?.balanceCents }, null, 1));
}
main().finally(() => db.$disconnect());

