// Cyrus game registry (client-safe, data only). Adding a game = adding a row here; the home
// game selector, the version picker and the copy all read from it. No official logos or art:
// each game gets a neutral two-letter text mark.
import { MB_VERSIONS, MB_DEFAULT_VERSION } from "../modbuilder/types";

export type CyrusGameStatus = "live" | "soon";

export type CyrusGame = {
  id: string;
  name: string;
  status: CyrusGameStatus;
  /** two-letter text mark drawn in a neutral tile */
  mark: string;
  /** what Cyrus builds for it, customer voice */
  builds: string;
  /** server software the mods target (shown next to the version) */
  loader: string;
  /** supported server versions, newest first */
  versions: readonly string[];
  defaultVersion?: string;
  /** legacy flag, true when status === "live" */
  available: boolean;
  note: string;
};

const g = (x: Omit<CyrusGame, "available" | "note">): CyrusGame => ({ ...x, available: x.status === "live", note: x.status === "live" ? x.builds : "Coming soon" });

export const CYRUS_GAMES: CyrusGame[] = [
  g({ id: "minecraft", name: "Minecraft", status: "live", mark: "MC", builds: "Paper and Purpur server plugins", loader: "Paper", versions: MB_VERSIONS, defaultVersion: MB_DEFAULT_VERSION }),
  g({ id: "ark", name: "ARK", status: "soon", mark: "AR", builds: "ARK: Survival Ascended server mods", loader: "ASA", versions: [] }),
  g({ id: "theisle", name: "The Isle", status: "soon", mark: "TI", builds: "The Isle Evrima server mods", loader: "Evrima", versions: [] }),
  g({ id: "palworld", name: "Palworld", status: "soon", mark: "PW", builds: "UE4SS server mods", loader: "UE4SS", versions: [] }),
  g({ id: "rust", name: "Rust", status: "soon", mark: "RS", builds: "Oxide / Carbon plugins", loader: "Oxide", versions: [] }),
  g({ id: "valheim", name: "Valheim", status: "soon", mark: "VH", builds: "BepInEx server mods", loader: "BepInEx", versions: [] }),
];

export const CYRUS_DEFAULT_GAME = CYRUS_GAMES.find((x) => x.status === "live")!;
export const cyrusGame = (id: string | null | undefined) => CYRUS_GAMES.find((x) => x.id === id) ?? CYRUS_DEFAULT_GAME;
/** "1.20.4 – 1.21.11" */
export const versionRange = (game: CyrusGame) => (game.versions.length ? (game.versions.length > 1 ? `${game.versions[game.versions.length - 1]} – ${game.versions[0]}` : game.versions[0]) : "");
