"use client";

// Cyrus's own small chrome INSIDE the portal content area (the portal keeps its real sidebar and
// top bar): a top-left projects switcher (projects per game, Custom Project, the Cyrus Pro card)
// plus "find a mod" and "new mod" buttons.
import { useEffect, useRef, useState } from "react";
import { CYRUS_GAMES, cyrusGame } from "@/lib/cyrus/games";
import { CyIcon, GameEmblem } from "./icons";

export function Switcher({ game, counts, building, onGame, onNew, onCustom, onUpgrade, onSearch }: {
  game: string;
  counts: Record<string, number>;
  building: number;
  onGame: (id: string) => void;
  onNew: () => void;
  onCustom: () => void;
  onUpgrade: () => void;
  onSearch: () => void;
}) {
  const [open, setOpen] = useState(false);
  const box = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const down = (e: MouseEvent) => { if (!box.current?.contains(e.target as Node)) setOpen(false); };
    const key = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", down); document.addEventListener("keydown", key);
    return () => { document.removeEventListener("mousedown", down); document.removeEventListener("keydown", key); };
  }, [open]);
  const g = cyrusGame(game);
  const pick = (f: () => void) => () => { setOpen(false); f(); };
  return (
    <div className="cy-sw" ref={box}>
      <button type="button" className="cy-sw-btn" onClick={() => setOpen((o) => !o)} aria-expanded={open} aria-haspopup="menu">
        <GameEmblem game={g.id} size={24} />
        <span className="cy-sw-t"><b>{g.name} Mods</b><em>Cyrus · Beta{building ? ` · ${building} building` : ""}</em></span>
        <CyIcon name="chev" size={15} />
      </button>
      <button type="button" className="cy-sw-ib" onClick={onSearch} title="Find a mod or file  P" aria-label="Find a mod or file"><CyIcon name="search" size={17} /></button>
      <button type="button" className="cy-sw-ib" onClick={onNew} title="New mod  N" aria-label="New mod"><CyIcon name="plus" size={17} /></button>
      {open && (
        <div className="cy-sw-pop" role="menu">
          <div className="cy-sw-h"><span>Projects</span><button type="button" className="cy-sw-add" onClick={pick(onNew)} aria-label="New mod"><CyIcon name="plus" size={14} /></button></div>
          {CYRUS_GAMES.map((x) => {
            const live = x.status === "live";
            return (
              <button key={x.id} type="button" role="menuitem" className={`cy-sw-i ${x.id === game ? "on" : ""} ${live ? "" : "soon"}`} onClick={pick(() => onGame(x.id))}>
                <GameEmblem game={x.id} size={22} />
                <span>{x.name} Mods</span>
                {live ? <em className="cy-sw-n">{counts[x.id] ?? 0}</em> : <em className="cy-sw-soon">Soon</em>}
              </button>
            );
          })}
          <button type="button" role="menuitem" className="cy-sw-i" onClick={pick(onCustom)}>
            <span className="cy-sw-ic"><CyIcon name="layers" size={18} tone="violet" /></span><span>Custom Project</span>
          </button>
          <div className="cy-pro">
            <div className="cy-pro-h"><CyIcon name="crown" size={20} tone="pink" /> Cyrus Pro</div>
            <p>Higher limits, faster models, advanced mod tools.</p>
            <button type="button" className="cy-pro-go" onClick={pick(onUpgrade)}>Upgrade <CyIcon name="crown" size={15} /></button>
          </div>
        </div>
      )}
    </div>
  );
